    window.isCurrentAdministrator = function() {
        const activeRole = (typeof resolveCurrentUserRole === 'function' ? resolveCurrentUserRole() : null) ||
                           sessionStorage.getItem('currentUserRole') ||
                           localStorage.getItem('currentUserRole') ||
                           (typeof currentUserRole !== 'undefined' ? currentUserRole : null) ||
                           '';
        return String(activeRole).trim().toLowerCase() === 'administrator';
    };

    window.canAccessLandingPage = function() {
        const activeRole = (typeof resolveCurrentUserRole === 'function' ? resolveCurrentUserRole() : null) ||
                           sessionStorage.getItem('currentUserRole') ||
                           localStorage.getItem('currentUserRole') ||
                           (typeof currentUserRole !== 'undefined' ? currentUserRole : null) ||
                           'Administrator';
        const roleLower = String(activeRole).trim().toLowerCase();
        return roleLower === 'administrator' || roleLower === 'supervisor';
    };

    const INSIGHTS_ACCESS_STORAGE_KEY = 'industria_insights_access';

    function getInsightsAccessControl() {
        try {
            const raw = localStorage.getItem(INSIGHTS_ACCESS_STORAGE_KEY);
            const parsed = raw ? JSON.parse(raw) : {};
            const allowedUsernames = Array.isArray(parsed && parsed.allowedUsernames)
                ? parsed.allowedUsernames.map(u => String(u || '').trim().toLowerCase()).filter(Boolean)
                : [];
            const allowedAgentIds = Array.isArray(parsed && parsed.allowedAgentIds)
                ? parsed.allowedAgentIds.map(id => String(id || '').trim()).filter(Boolean)
                : [];
            return {
                allowedUsernames: [...new Set(allowedUsernames)],
                allowedAgentIds: [...new Set(allowedAgentIds)]
            };
        } catch (e) {
            return { allowedUsernames: [], allowedAgentIds: [] };
        }
    }

    function saveInsightsAccessControl(cfg) {
        const clean = {
            allowedUsernames: [...new Set((cfg && cfg.allowedUsernames || []).map(u => String(u || '').trim().toLowerCase()).filter(Boolean))],
            allowedAgentIds: [...new Set((cfg && cfg.allowedAgentIds || []).map(id => String(id || '').trim()).filter(Boolean))]
        };
        try {
            localStorage.setItem(INSIGHTS_ACCESS_STORAGE_KEY, JSON.stringify(clean));
        } catch (e) {}
        if (window.IndustraSupabase && typeof window.IndustraSupabase.upsertSiteSetting === 'function') {
            window.IndustraSupabase.upsertSiteSetting('insights_access_control', clean).catch(err => {
                console.warn('Supabase insights_access_control sync failed:', err);
            });
        }
        return clean;
    }

    function userHasInsightsAccess(userObj, cfg) {
        if (!userObj) return false;
        const roleLower = String(userObj.role || '').trim().toLowerCase();
        if (roleLower === 'administrator') return true;
        const accessCfg = cfg || getInsightsAccessControl();
        const uname = String(userObj.username || '').trim().toLowerCase();
        if (uname && accessCfg.allowedUsernames.includes(uname)) return true;
        if (userObj.agentId !== undefined && userObj.agentId !== null && String(userObj.agentId).trim() !== '') {
            if (accessCfg.allowedAgentIds.includes(String(userObj.agentId).trim())) return true;
        }
        return false;
    }

    window.canAccessInsights = function() {
        const activeRole = (typeof resolveCurrentUserRole === 'function' ? resolveCurrentUserRole() : null) ||
                           sessionStorage.getItem('currentUserRole') ||
                           localStorage.getItem('currentUserRole') ||
                           (typeof currentUserRole !== 'undefined' ? currentUserRole : null) ||
                           'Administrator';
        if (String(activeRole).trim().toLowerCase() === 'administrator') return true;

        const cfg = getInsightsAccessControl();
        const userObj = (typeof getCurrentUserObj === 'function') ? getCurrentUserObj() : {
            username: sessionStorage.getItem('loggedInUser') || localStorage.getItem('loggedInUser') || '',
            role: activeRole
        };
        if (userHasInsightsAccess(userObj, cfg)) return true;

        const linkedAgent = (typeof getCurrentAgent === 'function') ? getCurrentAgent() : null;
        if (linkedAgent && linkedAgent.id !== undefined && linkedAgent.id !== null) {
            if (cfg.allowedAgentIds.includes(String(linkedAgent.id).trim())) return true;
        }
        return false;
    };

    window.applyRoleNavVisibility = function() {
        const activeRole = (typeof resolveCurrentUserRole === 'function' ? resolveCurrentUserRole() : null) ||
                           sessionStorage.getItem('currentUserRole') ||
                           localStorage.getItem('currentUserRole') ||
                           (typeof currentUserRole !== 'undefined' ? currentUserRole : null) ||
                           'Administrator';
        const isCurrentAdminRole = String(activeRole).trim().toLowerCase() === 'administrator';
        const canLanding = window.canAccessLandingPage();
        const canInsights = window.canAccessInsights();

        const navLanding = document.getElementById('nav-landing-page');
        const navInsights = document.getElementById('nav-insights');
        const insightsAccessCard = document.getElementById('insights-access-card');
        const initNavSettingsGeneral = document.getElementById('nav-settings-general');
        const initNavSettingsTimezone = document.getElementById('nav-settings-timezone');
        const initNavSettingsServer = document.getElementById('nav-settings-server');
        const initNavSettingsCosting = document.getElementById('nav-settings-costing');
        const initNavSettingsActivity = document.getElementById('nav-settings-activity');
        if (navLanding) navLanding.style.display = canLanding ? '' : 'none';
        if (navInsights) navInsights.style.display = canInsights ? '' : 'none';
        if (insightsAccessCard) insightsAccessCard.style.display = isCurrentAdminRole ? '' : 'none';
        if (initNavSettingsGeneral) initNavSettingsGeneral.style.display = isCurrentAdminRole ? '' : 'none';
        if (initNavSettingsTimezone) initNavSettingsTimezone.style.display = isCurrentAdminRole ? '' : 'none';
        if (initNavSettingsServer) initNavSettingsServer.style.display = isCurrentAdminRole ? '' : 'none';
        if (initNavSettingsCosting) initNavSettingsCosting.style.display = isCurrentAdminRole ? '' : 'none';
        if (initNavSettingsActivity) initNavSettingsActivity.style.display = isCurrentAdminRole ? '' : 'none';

        const adminLocToolbar = document.getElementById('admin-locations-toolbar');
        if (adminLocToolbar) {
            adminLocToolbar.style.display = isCurrentAdminRole ? 'flex' : 'none';
        }

        const overviewMaintCtrl = document.getElementById('overview-maintenance-control');
        if (overviewMaintCtrl) {
            overviewMaintCtrl.style.display = isCurrentAdminRole ? 'inline-flex' : 'none';
        }
        const settingsMaintCard = document.getElementById('card-settings-maintenance');
        if (settingsMaintCard) {
            settingsMaintCard.style.display = isCurrentAdminRole ? '' : 'none';
        }
        if (typeof window.renderMaintenanceModeUI === 'function') {
            window.renderMaintenanceModeUI();
        }
    };
    window.applyRoleNavVisibility();

    const ACTIVITY_LOGS_KEY = 'industria_activity_logs';
    let activityTableMissingOnSupabase = false;

    function getLocalActivityLogs() {
        try {
            const raw = localStorage.getItem(ACTIVITY_LOGS_KEY);
            const parsed = raw ? JSON.parse(raw) : [];
            return Array.isArray(parsed) ? parsed : [];
        } catch (e) {
            return [];
        }
    }

    function saveLocalActivityLogs(list) {
        try {
            const trimmed = Array.isArray(list) ? list.slice(0, 300) : [];
            localStorage.setItem(ACTIVITY_LOGS_KEY, JSON.stringify(trimmed));
        } catch (e) {}
    }

    window.logDashboardActivity = function({ category = 'System', action = 'Update', target = '', details = '', actorUsername = null, actorRole = null } = {}) {
        const resolvedActor = actorUsername || sessionStorage.getItem('loggedInUser') || localStorage.getItem('loggedInUser') || 'admin';
        const resolvedRole = actorRole || (typeof resolveCurrentUserRole === 'function' ? resolveCurrentUserRole() : null) || sessionStorage.getItem('currentUserRole') || localStorage.getItem('currentUserRole') || 'Administrator';
        const entry = {
            id: `act_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
            createdAt: new Date().toISOString(),
            actorUsername: String(resolvedActor),
            actorRole: String(resolvedRole),
            category: String(category),
            action: String(action),
            target: String(target || ''),
            details: String(details || '')
        };

        const logs = getLocalActivityLogs();
        logs.unshift(entry);
        saveLocalActivityLogs(logs);

        if (window.IndustraSupabase && typeof window.IndustraSupabase.insertActivityLog === 'function') {
            window.IndustraSupabase.insertActivityLog(entry).then(res => {
                if (res && res.tableMissing) {
                    activityTableMissingOnSupabase = true;
                }
            }).catch(() => {});
        }

        const subtabAct = document.getElementById('settings-subtab-activity');
        if (subtabAct && subtabAct.style.display !== 'none' && typeof window.renderActivityLog === 'function') {
            window.renderActivityLog();
        }
        return entry;
    };

    // Flush login event recorded in login.js to Supabase activity_logs
    (function flushPendingLoginActivity() {
        try {
            const rawPending = sessionStorage.getItem('__pending_login_activity');
            if (!rawPending) return;
            sessionStorage.removeItem('__pending_login_activity');
            const parsed = JSON.parse(rawPending);
            if (parsed && window.IndustraSupabase && typeof window.IndustraSupabase.insertActivityLog === 'function') {
                setTimeout(() => {
                    window.IndustraSupabase.insertActivityLog(parsed).then(res => {
                        if (res && res.tableMissing) activityTableMissingOnSupabase = true;
                    }).catch(() => {});
                }, 400);
            }
        } catch (e) {}
    })();

    function formatActivityDateTime(isoStr) {
        if (!isoStr) return '-';
        if (typeof window.formatDateTimeWithTimezone === 'function') {
            return window.formatDateTimeWithTimezone(isoStr);
        }
        const d = new Date(isoStr);
        return isNaN(d.getTime()) ? String(isoStr) : d.toLocaleString();
    }

    function getActionBadgeStyle(actionStr) {
        const a = String(actionStr || '').toLowerCase();
        if (a.includes('delete') || a.includes('remove') || a.includes('reject')) {
            return 'background: #fee2e2; color: #b91c1c; border: 1px solid #fecaca;';
        }
        if (a.includes('add') || a.includes('create') || a.includes('approve')) {
            return 'background: #dcfce7; color: #15803d; border: 1px solid #bbf7d0;';
        }
        if (a.includes('login')) {
            return 'background: #e0e7ff; color: #3730a3; border: 1px solid #c7d2fe;';
        }
        return 'background: #fef3c7; color: #b45309; border: 1px solid #fde68a;';
    }

    window.renderActivityLog = function() {
        const tbody = document.getElementById('activity-log-table-body');
        const totalEl = document.getElementById('activity-stat-total');
        const todayEl = document.getElementById('activity-stat-today');
        const usersEl = document.getElementById('activity-stat-users');
        const syncEl = document.getElementById('activity-sync-status-badge');
        const sqlBanner = document.getElementById('activity-sql-setup-banner');
        const showingBadge = document.getElementById('activity-log-showing-badge');
        const searchVal = (document.getElementById('activity-log-search')?.value || '').trim().toLowerCase();
        const catVal = document.getElementById('activity-log-category')?.value || 'All';
        const actVal = document.getElementById('activity-log-action')?.value || 'All';

        const logs = getLocalActivityLogs();
        const todayPrefix = new Date().toISOString().split('T')[0];

        if (totalEl) totalEl.textContent = logs.length;
        if (todayEl) todayEl.textContent = logs.filter(l => String(l.createdAt || '').startsWith(todayPrefix)).length;
        if (usersEl) usersEl.textContent = logs.filter(l => l.category === 'Admin Users').length;

        if (sqlBanner) sqlBanner.style.display = activityTableMissingOnSupabase ? 'block' : 'none';
        if (syncEl) {
            if (activityTableMissingOnSupabase) {
                syncEl.innerHTML = '<span style="color:#b45309;"><i class="fa-solid fa-hard-drive"></i> Local Cache (SQL Needed)</span>';
            } else if (window.IndustraSupabase && window.IndustraSupabase.getClient && window.IndustraSupabase.getClient()) {
                syncEl.innerHTML = '<span style="color:#059669;"><i class="fa-solid fa-cloud-check"></i> Supabase + Local Sync</span>';
            } else {
                syncEl.innerHTML = '<span style="color:#475569;"><i class="fa-solid fa-hard-drive"></i> Local Storage Cache</span>';
            }
        }

        const filtered = logs.filter(item => {
            if (catVal !== 'All' && String(item.category || '').toLowerCase() !== catVal.toLowerCase()) return false;
            if (actVal !== 'All' && !String(item.action || '').toLowerCase().includes(actVal.toLowerCase())) return false;
            if (searchVal) {
                const hay = [item.actorUsername, item.actorRole, item.category, item.action, item.target, item.details].filter(Boolean).join(' ').toLowerCase();
                if (!hay.includes(searchVal)) return false;
            }
            return true;
        });

        if (showingBadge) showingBadge.textContent = `${filtered.length} ${filtered.length === 1 ? 'Entry' : 'Entries'}`;
        if (!tbody) return;

        if (filtered.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; padding: 2.25rem; color: #94a3b8;"><i class="fa-solid fa-clock-rotate-left" style="font-size: 1.6rem; margin-bottom: 0.4rem; display: block; color: #cbd5e1;"></i>No matching dashboard activity logs found.</td></tr>';
            return;
        }

        tbody.innerHTML = filtered.slice(0, 250).map(item => `
            <tr>
                <td style="font-size: 0.8rem; color: var(--text-dark); white-space: nowrap;">${escapeHtml(formatActivityDateTime(item.createdAt))}</td>
                <td>
                    <div style="display: flex; flex-direction: column; gap: 2px;">
                        <strong style="font-size: 0.85rem; color: var(--text-dark);">${escapeHtml(item.actorUsername)}</strong>
                        <span style="font-size: 0.72rem; color: var(--text-muted);">${escapeHtml(item.actorRole)}</span>
                    </div>
                </td>
                <td><span class="badge-pill" style="background: #f1f5f9; color: #334155; font-size: 0.75rem; font-weight: 600; padding: 3px 9px;">${escapeHtml(item.category)}</span></td>
                <td><span class="status-badge" style="${getActionBadgeStyle(item.action)} font-size: 0.72rem; font-weight: 700; padding: 3px 8px;">${escapeHtml(item.action)}</span></td>
                <td style="font-size: 0.83rem; color: var(--text-dark); line-height: 1.4;">
                    ${item.target ? `<strong>${escapeHtml(item.target)}</strong>` : ''}
                    ${item.details ? `<div style="color: var(--text-muted); font-size: 0.78rem; margin-top: 2px;">${escapeHtml(item.details)}</div>` : ''}
                </td>
            </tr>
        `).join('');
    };

    window.loadActivityLogsFromSupabase = async function(showFeedback = false) {
        if (window.IndustraSupabase && typeof window.IndustraSupabase.fetchActivityLogs === 'function') {
            const res = await window.IndustraSupabase.fetchActivityLogs(250);
            if (res && res.tableMissing) {
                activityTableMissingOnSupabase = true;
            } else if (res && Array.isArray(res.rows)) {
                activityTableMissingOnSupabase = false;
                const localLogs = getLocalActivityLogs();
                const mergedMap = new Map();
                res.rows.forEach(r => {
                    const specs = (r.specs && typeof r.specs === 'object') ? r.specs : {};
                    const norm = {
                        id: String(r.id),
                        createdAt: r.created_at || specs.createdAt || '',
                        actorUsername: r.actor_username || specs.actorUsername || 'admin',
                        actorRole: r.actor_role || specs.actorRole || 'Administrator',
                        category: r.category || specs.category || 'System',
                        action: r.action || specs.action || 'Update',
                        target: r.target || specs.target || '',
                        details: r.details || specs.details || ''
                    };
                    mergedMap.set(norm.id, norm);
                });
                localLogs.forEach(l => {
                    if (l && l.id && !mergedMap.has(String(l.id))) {
                        mergedMap.set(String(l.id), l);
                    }
                });
                const merged = Array.from(mergedMap.values()).sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
                saveLocalActivityLogs(merged);
            }
        }
        window.renderActivityLog();
        if (showFeedback && typeof showDensityToast === 'function') {
            showDensityToast('Activity log refreshed.');
        }
    };

    window.copyActivitySqlSnippet = async function() {
        const pre = document.getElementById('activity-sql-snippet');
        const txt = pre ? pre.textContent : '';
        if (!txt) return;
        try {
            await navigator.clipboard.writeText(txt);
            if (typeof showDensityToast === 'function') showDensityToast('SQL copied! Paste it into Supabase > SQL Editor.');
            else alert('SQL copied to clipboard!');
        } catch (e) {
            prompt('Copy this SQL to Supabase SQL Editor:', txt);
        }
    };

    window.exportActivityLogsCsv = function() {
        const logs = getLocalActivityLogs();
        if (!logs.length) {
            alert('No activity logs available to export.');
            return;
        }
        const esc = v => '"' + String(v || '').replace(/"/g, '""') + '"';
        const rows = [['Date & Time', 'Username', 'Role', 'Category', 'Action', 'Target', 'Details'].map(esc).join(',')];
        logs.forEach(l => {
            rows.push([formatActivityDateTime(l.createdAt), l.actorUsername, l.actorRole, l.category, l.action, l.target, l.details].map(esc).join(','));
        });
        const blob = new Blob([rows.join('\n')], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `myfactoryspace-activity-log-${new Date().toISOString().split('T')[0]}.csv`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    };

    function escapeHtml(str) {
        return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }
    window.escapeHtml = escapeHtml;

    function safeJsonParse(key, fallback) {
        try {
            const str = localStorage.getItem(key);
            if (str && typeof str === 'string' && (str.startsWith('{') || str.startsWith('['))) {
                return JSON.parse(str);
            }
        } catch (e) {
            console.warn(`safeJsonParse failed for "${key}", removing invalid data:`, e);
            try { localStorage.removeItem(key); } catch (err) {}
        }
        return fallback;
    }

    function stripBase64FromDashboardProp(p) {
        if (!p || typeof p !== 'object') return p;
        const copy = Object.assign({}, p);
        if (copy.photosCleared === true) {
            copy.images = [];
            copy.rawImages = [];
            copy.image = '';
            copy.rawImage = '';
            return copy;
        }
        const validRemote = (Array.isArray(copy.images) ? copy.images : []).filter(u => typeof u === 'string' && u.trim() && !u.startsWith('data:'));
        const validRaw = (Array.isArray(copy.rawImages) ? copy.rawImages : []).filter(u => typeof u === 'string' && u.trim() && !u.startsWith('data:'));
        if (validRaw.length > 0) {
            copy.rawImages = validRaw;
            copy.images = validRemote.length > 0 ? validRemote : validRaw;
        } else if (validRemote.length > 0) {
            copy.images = validRemote;
            copy.rawImages = validRemote;
        } else {
            copy.images = [(copy.id && typeof defaultCleanImages !== 'undefined' && defaultCleanImages[copy.id]) ? defaultCleanImages[copy.id] : 'assets/images/hero.jpg'];
            copy.rawImages = copy.images;
        }
        copy.image = copy.images[0];
        copy.rawImage = copy.rawImages[0] || copy.image;
        return copy;
    }

    function purgeDashboardLocalStorageBloat() {
        try {
            const rawProps = localStorage.getItem('industria_properties');
            if (rawProps && rawProps.includes('data:image')) {
                const parsed = JSON.parse(rawProps);
                if (Array.isArray(parsed)) {
                    localStorage.setItem('industria_properties', JSON.stringify(parsed.map(stripBase64FromDashboardProp)));
                }
            }
        } catch (_) {}
        try {
            const rawWm = localStorage.getItem('industria_watermark_settings');
            if (rawWm && rawWm.length > 120000) {
                localStorage.removeItem('industria_watermark_settings');
            }
        } catch (_) {}
    }

    function safeLocalStorageSet(key, value) {
        const valueStr = typeof value === 'string' ? value : JSON.stringify(value);
        try {
            localStorage.setItem(key, valueStr);
            return true;
        } catch (e) {
            console.warn(`localStorage.setItem quota notice for key "${key}", purging base64 cache and retrying...`, e);
            purgeDashboardLocalStorageBloat();
            try {
                localStorage.setItem(key, valueStr);
                return true;
            } catch (err2) {
                if (key === 'industria_properties' && (Array.isArray(value) || typeof value === 'string')) {
                    try {
                        const rawProps = typeof value === 'string' ? JSON.parse(value) : value;
                        if (Array.isArray(rawProps)) {
                            localStorage.setItem(key, JSON.stringify(rawProps.map(stripBase64FromDashboardProp)));
                            return true;
                        }
                    } catch (_) {}
                }
                console.warn('Silent fallback storage write skipped:', err2);
            }
            return false;
        }
    }
    window.safeLocalStorageSet = safeLocalStorageSet;

    function normalizeStorageRefUrl(u) {
        if (!u || typeof u !== 'string') return '';
        const clean = u.split('?')[0].trim();
        if (window.IndustraSupabase && typeof window.IndustraSupabase.parseStoragePublicUrl === 'function') {
            return window.IndustraSupabase.parseStoragePublicUrl(clean) ? clean : '';
        }
        return /^https:\/\/[^\/]+\/storage\/v1\/object\/public\//i.test(clean) ? clean : '';
    }

    function collectAllActiveStorageUrls() {
        const active = new Set();
        const addUrl = (u) => {
            const norm = normalizeStorageRefUrl(u);
            if (norm) active.add(norm);
        };
        const addPropUrls = (p) => {
            if (!p || typeof p !== 'object') return;
            addUrl(p.image);
            addUrl(p.rawImage);
            if (Array.isArray(p.images)) p.images.forEach(addUrl);
            if (Array.isArray(p.rawImages)) p.rawImages.forEach(addUrl);
        };

        try { (Array.isArray(properties) ? properties : []).forEach(addPropUrls); } catch (_) {}
        try { (safeJsonParse('industria_properties', []) || []).forEach(addPropUrls); } catch (_) {}
        try {
            if (typeof currentPropertyImages !== 'undefined' && Array.isArray(currentPropertyImages)) currentPropertyImages.forEach(addUrl);
            if (typeof currentRawPropertyImages !== 'undefined' && Array.isArray(currentRawPropertyImages)) currentRawPropertyImages.forEach(addUrl);
        } catch (_) {}

        try {
            const agentLists = [
                ...(typeof agents !== 'undefined' && Array.isArray(agents) ? agents : []),
                ...(Array.isArray(window.__liveAgents) ? window.__liveAgents : []),
                ...(safeJsonParse('industria_agents', []) || [])
            ];
            agentLists.forEach(a => {
                if (!a || typeof a !== 'object') return;
                addUrl(a.image);
                addUrl(a.photo);
            });
        } catch (_) {}

        try {
            const activeBranding = (typeof getBrandingSettings === 'function' ? getBrandingSettings() : null) || (settings && settings.branding);
            if (activeBranding) {
                addUrl(activeBranding.logoUrl);
                addUrl(activeBranding.faviconUrl);
            }
            const storedBranding = safeJsonParse('industria_branding_settings', null);
            if (storedBranding) {
                addUrl(storedBranding.logoUrl);
                addUrl(storedBranding.faviconUrl);
            }
            if (settings && settings.branding) {
                addUrl(settings.branding.logoUrl);
                addUrl(settings.branding.faviconUrl);
            }
            const liveLogoInput = document.getElementById('setting-brand-logo-url');
            if (liveLogoInput && liveLogoInput.value) addUrl(liveLogoInput.value);
            const liveFavInput = document.getElementById('setting-brand-favicon-url');
            if (liveFavInput && liveFavInput.value) addUrl(liveFavInput.value);
        } catch (_) {}

        try {
            const wm = (typeof watermarkSettings !== 'undefined' ? watermarkSettings : null) || safeJsonParse('industria_watermark_settings', null);
            if (wm && wm.logoBase64) addUrl(wm.logoBase64);
            const wmStored = safeJsonParse('industria_watermark_settings', null);
            if (wmStored && wmStored.logoBase64) addUrl(wmStored.logoBase64);
        } catch (_) {}

        try {
            const locMap = safeJsonParse('industria_location_settings', {});
            if (locMap && typeof locMap === 'object') {
                Object.values(locMap).forEach(loc => {
                    if (!loc || typeof loc !== 'object') return;
                    addUrl(loc.heroImage);
                    addUrl(loc.cardImage);
                });
            }
        } catch (_) {}

        try {
            const insList = safeJsonParse('industria_insights_articles', []);
            if (Array.isArray(insList)) {
                insList.forEach(art => {
                    if (!art || typeof art !== 'object') return;
                    addUrl(art.coverImage);
                    addUrl(art.authorAvatar);
                    if (art.visualInfographic && art.visualInfographic.photoUrl) addUrl(art.visualInfographic.photoUrl);
                });
            }
        } catch (_) {}

        return active;
    }

    async function cleanupUnreferencedStorageUrls(candidateUrls) {
        if (!window.IndustraSupabase || typeof window.IndustraSupabase.deleteStorageObjects !== 'function') return 0;
        const list = Array.isArray(candidateUrls) ? candidateUrls : [candidateUrls];
        const activeSet = collectAllActiveStorageUrls();
        const orphans = [];
        list.forEach(raw => {
            const norm = normalizeStorageRefUrl(raw);
            if (norm && !activeSet.has(norm) && !orphans.includes(norm)) {
                orphans.push(norm);
            }
        });
        if (!orphans.length) return 0;
        return await window.IndustraSupabase.deleteStorageObjects(orphans);
    }
    window.cleanupUnreferencedStorageUrls = cleanupUnreferencedStorageUrls;

