    function setPropertyPhotoUploadStatus(message, tone = 'warn') {
        const statusEl = document.getElementById('property-photo-upload-status');
        if (!statusEl) return;
        const text = String(message || '').trim();
        if (!text) {
            statusEl.style.display = 'none';
            statusEl.textContent = '';
            statusEl.className = '';
            return;
        }
        statusEl.className = tone === 'error' ? 'is-error' : (tone === 'success' ? 'is-success' : '');
        statusEl.textContent = text;
        statusEl.style.display = 'block';
    }

    function buildFallbackCroppedCanvas(src, targetW, targetH, aspectRatio, fillColor) {
        return new Promise((resolve) => {
            if (!src) { resolve(null); return; }
            const img = new Image();
            if (/^https?:\/\//i.test(String(src))) img.crossOrigin = 'anonymous';
            img.onload = () => {
                try {
                    const iw = img.naturalWidth || img.width || targetW || 1200;
                    const ih = img.naturalHeight || img.height || targetH || 800;
                    const ratio = (Number.isFinite(aspectRatio) && aspectRatio > 0) ? aspectRatio : (iw / Math.max(1, ih));
                    let sx = 0, sy = 0, sw = iw, sh = ih;
                    if (iw / ih > ratio) {
                        sw = Math.round(ih * ratio);
                        sx = Math.round((iw - sw) / 2);
                    } else {
                        sh = Math.round(iw / ratio);
                        sy = Math.round((ih - sh) / 2);
                    }
                    const outW = targetW || Math.min(1200, sw);
                    const outH = targetH || Math.max(1, Math.round(outW / ratio));
                    const canvas = document.createElement('canvas');
                    canvas.width = outW;
                    canvas.height = outH;
                    const ctx = canvas.getContext('2d');
                    if (fillColor) {
                        ctx.fillStyle = fillColor;
                        ctx.fillRect(0, 0, outW, outH);
                    }
                    ctx.imageSmoothingEnabled = true;
                    ctx.imageSmoothingQuality = 'high';
                    ctx.drawImage(img, sx, sy, sw, sh, 0, 0, outW, outH);
                    resolve(canvas);
                } catch (_) {
                    resolve(null);
                }
            };
            img.onerror = () => resolve(null);
            img.src = src;
        });
    }

