    // Function to calculate and render LocalStorage capacity usage
    window.updateLocalStorageStatsUI = function() {
        let totalBytes = 0;
        try {
            for (let key in localStorage) {
                if (localStorage.hasOwnProperty(key)) {
                    totalBytes += (localStorage[key].length + key.length) * 2;
                }
            }
        } catch(e) {}
        
        const usedMB = (totalBytes / (1024 * 1024)).toFixed(2);
        const maxMB = 5.0;
        const percent = Math.min(100, Math.max(0, (totalBytes / (5 * 1024 * 1024)) * 100)).toFixed(1);
        
        const textEl = document.getElementById('storage-usage-text');
        const barEl = document.getElementById('storage-usage-bar');
        
        if (textEl) {
            textEl.innerHTML = `<strong>${usedMB} MB</strong> / ${maxMB.toFixed(2)} MB (${percent}% Used)`;
        }
        if (barEl) {
            barEl.style.width = percent + '%';
            if (parseFloat(percent) > 85) {
                barEl.style.background = 'linear-gradient(90deg, #ef4444, #dc2626)';
            } else if (parseFloat(percent) > 60) {
                barEl.style.background = 'linear-gradient(90deg, #f59e0b, #d97706)';
            } else {
                barEl.style.background = 'linear-gradient(90deg, #10b981, #0077b6)';
            }
        }
    };

    window.checkSupabaseStorageUsage = async function() {
        const textEl = document.getElementById('supabase-storage-usage-text');
        const barEl = document.getElementById('supabase-storage-usage-bar');
        const statusBadge = document.getElementById('supabase-status-badge');
        const countPropsEl = document.getElementById('supabase-count-properties');
        const countUsersEl = document.getElementById('supabase-count-users');
        const countLeadsEl = document.getElementById('supabase-count-leads');

        if (!window.IndustraSupabase) {
            if (statusBadge) {
                statusBadge.style.background = '#fee2e2';
                statusBadge.style.color = '#dc2626';
                statusBadge.style.borderColor = '#fca5a5';
                statusBadge.innerHTML = '<i class="fa-solid fa-circle-xmark"></i> Disconnected';
            }
            if (textEl) textEl.textContent = 'Supabase client not initialized';
            return;
        }

        try {
            if (typeof window.IndustraSupabase.ensurePublicConfigLoaded === 'function') {
                await window.IndustraSupabase.ensurePublicConfigLoaded();
            }
            const client = window.IndustraSupabase.getClient();
            if (!client) throw new Error('No client');

            const [propsRes, usersRes, leadsRes, parksRes] = await Promise.all([
                client.from('properties').select('id', { count: 'exact', head: true }),
                client.from('app_users').select('id', { count: 'exact', head: true }),
                client.from('leads').select('id', { count: 'exact', head: true }),
                client.from('parks').select('id', { count: 'exact', head: true })
            ]);

            const propCount = propsRes.count || 0;
            const userCount = usersRes.count || 0;
            const leadCount = leadsRes.count || 0;
            const parkCount = parksRes.count || 0;

            if (countPropsEl) countPropsEl.textContent = `${propCount} Listing${propCount !== 1 ? 's' : ''}`;
            if (countUsersEl) countUsersEl.textContent = `${userCount} Account${userCount !== 1 ? 's' : ''}`;
            if (countLeadsEl) countLeadsEl.textContent = `${leadCount} Inquir${leadCount !== 1 ? 'ies' : 'y'}`;
            const countParksEl = document.getElementById('supabase-count-parks');
            if (countParksEl) countParksEl.textContent = `${parkCount} Park${parkCount !== 1 ? 's' : ''}`;

            if (typeof updateLastExportBadge === 'function') {
                updateLastExportBadge();
            }
            if (typeof updateLastRestoreBadge === 'function') {
                updateLastRestoreBadge();
            }

            const { data: allProps } = await client.from('properties').select('*');
            const bytes = new Blob([JSON.stringify(allProps || [])]).size;
            const usedMB = (bytes / (1024 * 1024)).toFixed(3);
            const maxMB = 500.0;
            const percent = Math.max(0.01, ((bytes / (500 * 1024 * 1024)) * 100)).toFixed(3);

            if (textEl) {
                textEl.innerHTML = `<strong>${usedMB} MB</strong> / ${maxMB.toFixed(0)} MB Free Tier Quota (${percent}% Used)`;
            }

            if (barEl) {
                barEl.style.width = Math.max(1, parseFloat(percent)) + '%';
            }

            if (statusBadge) {
                statusBadge.style.background = '#dcfce7';
                statusBadge.style.color = '#15803d';
                statusBadge.style.borderColor = '#bbf7d0';
                statusBadge.innerHTML = '<i class="fa-solid fa-circle-check"></i> Connected & Active';
            }

        } catch (e) {
            console.warn('Error checking Supabase storage:', e);
            if (textEl) textEl.textContent = 'Active (Connected)';
        }

        if (typeof window.refreshMediaStorageUsageUI === 'function') {
            await window.refreshMediaStorageUsageUI(true);
        }
        if (typeof window.renderPrimarySupabaseConfigUI === 'function') {
            window.renderPrimarySupabaseConfigUI();
        }
        if (typeof window.renderMediaStorageConfigUI === 'function') {
            window.renderMediaStorageConfigUI();
        }
    };

    window.refreshMediaStorageUsageUI = async function(forceRefresh = false) {
        const textEl = document.getElementById('media-storage-usage-text');
        const barEl = document.getElementById('media-storage-usage-bar');
        const noteEl = document.getElementById('media-storage-status-note');
        const badgeEl = document.getElementById('media-storage-provider-badge');
        const bucketLabelEl = document.getElementById('media-storage-bucket-label');
        if (!textEl || !window.IndustraSupabase) return;

        const isR2 = typeof window.IndustraSupabase.isUsingR2Storage === 'function' && window.IndustraSupabase.isUsingR2Storage();
        const mediaCfg = typeof window.IndustraSupabase.getMediaStorageConfig === 'function'
            ? window.IndustraSupabase.getMediaStorageConfig()
            : { provider: 'supabase' };
        const activeBucket = typeof window.IndustraSupabase.getPrimaryBucketName === 'function'
            ? window.IndustraSupabase.getPrimaryBucketName()
            : 'property-images';
        const isCustomStorage = typeof window.IndustraSupabase.isCustomPrimaryStorageActive === 'function'
            && window.IndustraSupabase.isCustomPrimaryStorageActive();

        if (bucketLabelEl) {
            bucketLabelEl.textContent = isR2 ? (mediaCfg.r2Prefix ? `R2 / ${mediaCfg.r2Prefix}` : 'Cloudflare R2') : activeBucket;
        }
        if (badgeEl) {
            if (isR2) {
                badgeEl.style.background = '#fff7ed';
                badgeEl.style.color = '#c2410c';
                badgeEl.style.borderColor = '#fed7aa';
                badgeEl.textContent = 'Cloudflare R2 (10 GB Free, $0 Egress)';
            } else if (isCustomStorage) {
                badgeEl.style.background = '#ecfdf5';
                badgeEl.style.color = '#047857';
                badgeEl.style.borderColor = '#a7f3d0';
                badgeEl.textContent = 'Custom Supabase (< 500 MB Guard)';
            } else {
                badgeEl.style.background = '#e0f2fe';
                badgeEl.style.color = '#0369a1';
                badgeEl.style.borderColor = '#bae6fd';
                badgeEl.textContent = 'Supabase (< 500 MB Guard)';
            }
        }

        try {
            const summary = await window.IndustraSupabase.getStorageUsageSummary(activeBucket, { forceRefresh });
            if (summary && summary.known) {
                const limitMB = summary.limitMB || (isR2 ? 10240 : 500);
                const pctNum = limitMB > 0 ? Math.min(100, (summary.totalMB / limitMB) * 100) : 0;
                const pctStr = pctNum.toFixed(1);
                textEl.innerHTML = `<strong>${summary.totalMB.toFixed(2)} MB</strong> / ${limitMB >= 1024 ? '10 GB Free' : limitMB + ' MB Target'} (${summary.fileCount} files • ${pctStr}%)`;

                if (barEl) {
                    barEl.style.width = Math.max(2, Math.min(100, pctNum)) + '%';
                    if (!isR2 && summary.totalMB > 500) {
                        barEl.style.background = 'linear-gradient(90deg, #ef4444, #dc2626)';
                    } else if (!isR2 && summary.totalMB >= 450) {
                        barEl.style.background = 'linear-gradient(90deg, #f59e0b, #d97706)';
                    } else {
                        barEl.style.background = isR2
                            ? 'linear-gradient(90deg, #f97316, #ea580c)'
                            : 'linear-gradient(90deg, #0284c7, #0ea5e9)';
                    }
                }

                if (noteEl) {
                    if (!isR2 && summary.totalMB > 500) {
                        noteEl.style.color = '#b91c1c';
                        noteEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> Bucket is at <strong>${summary.totalMB.toFixed(2)} MB</strong> across ${summary.fileCount} files (above 500 MB target). Run <strong>Scan &amp; Clean Orphaned Photos Now</strong> or delete orphaned <code>2026-09</code>/<code>2026-10</code> duplicates in Supabase Studio.`;
                    } else {
                        noteEl.style.color = 'var(--text-muted)';
                        noteEl.textContent = isR2
                            ? `Cloudflare R2 active with SHA-256 content deduplication & $0 egress (${summary.fileCount} stored files).`
                            : `Healthy! SHA-256 deduplication, auto-cleanup, and the 500 MB upload guard keep storage lean.`;
                    }
                }
            } else {
                const errMsg = (summary && summary.error) ? summary.error : 'Storage usage unavailable right now.';
                textEl.textContent = (summary && summary.quotaExceeded) ? 'Quota Exceeded / Locked (> 500 MB)' : 'Status Unavailable';
                if (barEl) {
                    barEl.style.width = (summary && summary.quotaExceeded) ? '100%' : '5%';
                    barEl.style.background = (summary && summary.quotaExceeded) ? 'linear-gradient(90deg, #ef4444, #dc2626)' : '#cbd5e1';
                }
                if (noteEl) {
                    noteEl.style.color = '#b91c1c';
                    noteEl.textContent = errMsg;
                }
            }
        } catch (err) {
            textEl.textContent = 'Check failed';
            if (noteEl) noteEl.textContent = err && err.message ? err.message : String(err);
        }
    };

    window.downloadActiveStorageManifest = function() {
        const urls = collectAllActiveStorageUrls();
        const rows = Array.from(urls).sort().map(u => {
            const parsed = (window.IndustraSupabase && typeof window.IndustraSupabase.parseStoragePublicUrl === 'function')
                ? window.IndustraSupabase.parseStoragePublicUrl(u)
                : null;
            const fname = parsed && parsed.path ? parsed.path : u.split('/').pop();
            return `${fname}\t${u}`;
        });
        const header = [
            `# Active Media Keep-List Generated: ${new Date().toISOString()}`,
            `# Total Protected Active Files: ${rows.length}`,
            '# DO NOT DELETE these filenames from storage.',
            'FILENAME\tFULL_URL',
            ''
        ].join('\n');
        const blob = new Blob([header + rows.join('\n')], { type: 'text/plain;charset=utf-8' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `active-storage-keep-list-${new Date().toISOString().slice(0, 10)}.txt`;
        document.body.appendChild(link);
        link.click();
        setTimeout(() => {
            URL.revokeObjectURL(link.href);
            link.remove();
        }, 500);
    };

    window.scanAndCleanOrphanStorage = async function() {
        if (!window.IndustraSupabase || typeof window.IndustraSupabase.listAllBucketObjects !== 'function') return;
        const btn = document.getElementById('btn-scan-clean-orphans');
        const origHtml = btn ? btn.innerHTML : '';
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Scanning Bucket...';
        }
        try {
            const activeBucket = typeof window.IndustraSupabase.getPrimaryBucketName === 'function'
                ? window.IndustraSupabase.getPrimaryBucketName()
                : 'property-images';
            const scan = await window.IndustraSupabase.listAllBucketObjects(activeBucket);
            if (!scan || !scan.known) {
                alert(`Could not list storage bucket right now:\n${(scan && scan.error) || 'Unknown error'}\n\nIf Supabase returned a storage quota lock (HTTP 402), download the Active Keep-List (.txt) first and remove old 2026-09/2026-10 duplicate files inside Supabase Dashboard > Storage.`);
                return;
            }

            const activeUrls = collectAllActiveStorageUrls();
            const activeNames = new Set();
            activeUrls.forEach(u => {
                const parsed = window.IndustraSupabase.parseStoragePublicUrl(u);
                if (parsed && parsed.path) activeNames.add(parsed.path);
                const tail = String(u || '').split('/').pop().split('?')[0];
                if (tail) activeNames.add(tail);
            });

            const orphans = [];
            let orphanBytes = 0;
            let activeFound = 0;
            (scan.items || []).forEach(item => {
                if (!item || !item.name || item.name.endsWith('/') || item.name === '.emptyFolderPlaceholder') return;
                const cleanUrl = normalizeStorageRefUrl(item.url);
                const baseName = item.name.split('/').pop();
                const isReferenced = (cleanUrl && activeUrls.has(cleanUrl)) || activeNames.has(item.name) || activeNames.has(baseName);
                if (isReferenced) {
                    activeFound++;
                } else {
                    orphans.push(item);
                    orphanBytes += Number(item.size || 0);
                }
            });

            if (orphans.length === 0) {
                alert(`✅ Bucket is clean! Checked ${scan.fileCount} files (${scan.totalMB} MB). Zero orphaned images found.`);
                return;
            }

            const orphanMB = (orphanBytes / (1024 * 1024)).toFixed(2);
            const confirmed = confirm(
                `Storage Orphan Scan Complete (${scan.provider.toUpperCase()}):\n\n`
                + `• Total files scanned: ${scan.fileCount} (${scan.totalMB} MB)\n`
                + `• Protected active files: ${activeFound}\n`
                + `• Unused / orphaned duplicates: ${orphans.length} (${orphanMB} MB)\n\n`
                + `Permanently delete these ${orphans.length} orphaned files now?`
            );
            if (!confirmed) return;

            if (btn) btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Deleting Orphans...';
            const delCount = await window.IndustraSupabase.deleteStorageObjects(orphans.map(o => o.url).filter(Boolean));
            const lastErr = window.IndustraSupabase._lastStorageError;
            if (delCount === 0 && lastErr) {
                alert(`⚠️ Supabase blocked API deletion (${lastErr}).\n\nDownload your Active Keep-List (.txt) and clear the old duplicate files directly in Supabase Studio Storage first.`);
            } else {
                alert(`✅ Removed ${delCount} orphaned files! Refreshing usage meter...`);
                if (typeof window.logDashboardActivity === 'function') {
                    window.logDashboardActivity({
                        category: 'Storage',
                        action: 'Cleanup',
                        target: scan.provider === 'r2' ? 'Cloudflare R2' : (scan.bucket || 'property-images'),
                        details: `Deleted ${delCount} orphaned duplicate image(s)`
                    });
                }
            }
            await window.refreshMediaStorageUsageUI(true);
        } finally {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = origHtml;
            }
        }
    };

    window.toggleMediaStorageFields = function() {
        const sel = document.getElementById('media-storage-provider');
        const fields = document.getElementById('r2-config-fields');
        const testBtn = document.getElementById('btn-test-r2-conn');
        const isR2 = sel && sel.value === 'r2';
        if (fields) fields.style.display = isR2 ? 'flex' : 'none';
        if (testBtn) testBtn.style.display = isR2 ? 'inline-flex' : 'none';
    };

    window.renderMediaStorageConfigUI = function() {
        if (!window.IndustraSupabase || typeof window.IndustraSupabase.getMediaStorageConfig !== 'function') return;
        const cfg = window.IndustraSupabase.getMediaStorageConfig();
        const sel = document.getElementById('media-storage-provider');
        const pubInp = document.getElementById('r2-public-url');
        const apiInp = document.getElementById('r2-api-endpoint');
        const prefixInp = document.getElementById('r2-key-prefix');
        const tokenInp = document.getElementById('r2-admin-token');
        const headerBadge = document.getElementById('media-provider-header-badge');

        if (sel) sel.value = cfg.provider || 'supabase';
        if (pubInp) pubInp.value = cfg.r2PublicUrl || '';
        if (apiInp) apiInp.value = cfg.r2Endpoint || '/api/r2-storage';
        if (prefixInp) prefixInp.value = cfg.r2Prefix || '';
        if (tokenInp && typeof window.IndustraSupabase.getR2AdminToken === 'function') {
            tokenInp.value = window.IndustraSupabase.getR2AdminToken() || '';
        }

        if (headerBadge) {
            const isCustomStorage = typeof window.IndustraSupabase.isCustomPrimaryStorageActive === 'function'
                && window.IndustraSupabase.isCustomPrimaryStorageActive();
            const activeBucket = typeof window.IndustraSupabase.getPrimaryBucketName === 'function'
                ? window.IndustraSupabase.getPrimaryBucketName()
                : 'property-images';
            if (window.IndustraSupabase.isUsingR2Storage()) {
                headerBadge.style.background = '#fff7ed';
                headerBadge.style.color = '#c2410c';
                headerBadge.style.borderColor = '#fed7aa';
                headerBadge.textContent = 'Active: Cloudflare R2 (10 GB Free)';
            } else if (isCustomStorage) {
                headerBadge.style.background = '#ecfdf5';
                headerBadge.style.color = '#047857';
                headerBadge.style.borderColor = '#a7f3d0';
                headerBadge.textContent = `Active: Custom Supabase (${activeBucket})`;
            } else {
                headerBadge.style.background = '#dcfce7';
                headerBadge.style.color = '#15803d';
                headerBadge.style.borderColor = '#bbf7d0';
                headerBadge.textContent = 'Active: Cleaned Supabase (< 500 MB)';
            }
        }
        window.toggleMediaStorageFields();
    };

    function setMediaStorageStatusBanner(type, html) {
        const el = document.getElementById('media-storage-config-status');
        if (!el) return;
        el.style.display = 'block';
        if (type === 'success') {
            el.style.background = '#dcfce7';
            el.style.color = '#166534';
            el.style.border = '1px solid #bbf7d0';
        } else if (type === 'error') {
            el.style.background = '#fee2e2';
            el.style.color = '#991b1b';
            el.style.border = '1px solid #fecaca';
        } else {
            el.style.background = '#e0f2fe';
            el.style.color = '#075985';
            el.style.border = '1px solid #bae6fd';
        }
        el.innerHTML = html;
    }

    function readMediaStorageForm() {
        const provider = (document.getElementById('media-storage-provider') || {}).value === 'r2' ? 'r2' : 'supabase';
        const r2PublicUrl = String((document.getElementById('r2-public-url') || {}).value || '').trim().replace(/\/+$/, '');
        const r2Endpoint = String((document.getElementById('r2-api-endpoint') || {}).value || '/api/r2-storage').trim() || '/api/r2-storage';
        const r2Prefix = String((document.getElementById('r2-key-prefix') || {}).value || '').trim().replace(/^\/+|\/+$/g, '');
        const token = String((document.getElementById('r2-admin-token') || {}).value || '').trim();
        return { cfg: { provider, r2Endpoint, r2PublicUrl, r2Prefix }, token };
    }

    window.testMediaR2Connection = async function() {
        if (!window.IndustraSupabase || typeof window.IndustraSupabase.testR2Connection !== 'function') return;
        const { cfg, token } = readMediaStorageForm();
        setMediaStorageStatusBanner('info', '<i class="fa-solid fa-spinner fa-spin"></i> Testing Cloudflare R2 presigner & bucket connection...');
        const res = await window.IndustraSupabase.testR2Connection(cfg, token);
        setMediaStorageStatusBanner(res.ok ? 'success' : 'error', escapeHtml(res.message || 'Connection check finished.'));
    };

    window.saveMediaStorageSettings = async function() {
        const { cfg, token } = readMediaStorageForm();
        if (cfg.provider === 'r2') {
            if (!/^https:\/\/.+/i.test(cfg.r2PublicUrl)) {
                setMediaStorageStatusBanner('error', 'Please enter a valid HTTPS Cloudflare R2 Public Base URL before switching to R2.');
                return;
            }
            if (!token) {
                setMediaStorageStatusBanner('error', 'Please enter your R2 Admin Upload Token (matching Vercel env R2_API_TOKEN).');
                return;
            }
        }

        if (window.IndustraSupabase) {
            window.IndustraSupabase.setMediaStorageConfig(cfg);
            window.IndustraSupabase.setR2AdminToken(token);
        }
        settings.mediaStorage = cfg;
        window.__liveSiteSettings = settings;
        safeLocalStorageSet('industria_settings', settings);
        await saveGeneralSettingsToSupabase();
        window.renderMediaStorageConfigUI();
        await window.refreshMediaStorageUsageUI(true);

        setMediaStorageStatusBanner(
            'success',
            cfg.provider === 'r2'
                ? `Saved! New image uploads now route to Cloudflare R2 (<strong>${escapeHtml(cfg.r2PublicUrl)}</strong>) with $0 egress.`
                : 'Saved! Primary uploads continue using cleaned Supabase Storage with the < 500 MB budget guard active.'
        );
    };

    // --- CUSTOM / SECONDARY PRIMARY SUPABASE ACCOUNT CONFIGURATION (SETTINGS > SERVER) ---
    function extractSupabaseProjectRef(url) {
        const m = String(url || '').trim().match(/^https:\/\/([a-z0-9-]+)\.supabase\.co/i);
        return m ? m[1] : '';
    }

    function buildVisitorRpcsSql() {
        return `-- Visitor Analytics RPC Functions (required by Dashboard > Overview KPIs & Traffic Charts)
CREATE OR REPLACE FUNCTION public.get_daily_visitor_stats()
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH bounds AS (
    SELECT date_trunc('day', now() AT TIME ZONE 'Asia/Kuala_Lumpur') AS today_start
  )
  SELECT jsonb_build_object(
    'today_visitors', (
      SELECT count(DISTINCT visitor_id)
      FROM public.page_views, bounds
      WHERE (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') >= bounds.today_start
    ),
    'yesterday_visitors', (
      SELECT count(DISTINCT visitor_id)
      FROM public.page_views, bounds
      WHERE (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') >= bounds.today_start - interval '1 day'
        AND (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') < bounds.today_start
    ),
    'today_views', (
      SELECT count(*)
      FROM public.page_views, bounds
      WHERE (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') >= bounds.today_start
    )
  );
$$;

CREATE OR REPLACE FUNCTION public.get_visitor_stats()
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH bounds AS (
    SELECT date_trunc('month', now() AT TIME ZONE 'Asia/Kuala_Lumpur') AS month_start
  )
  SELECT jsonb_build_object(
    'this_month', (
      SELECT count(DISTINCT visitor_id)
      FROM public.page_views, bounds
      WHERE (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') >= bounds.month_start
    ),
    'last_month', (
      SELECT count(DISTINCT visitor_id)
      FROM public.page_views, bounds
      WHERE (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') >= bounds.month_start - interval '1 month'
        AND (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') < bounds.month_start
    ),
    'views_this_month', (
      SELECT count(*)
      FROM public.page_views, bounds
      WHERE (created_at AT TIME ZONE 'Asia/Kuala_Lumpur') >= bounds.month_start
    )
  );
$$;

CREATE OR REPLACE FUNCTION public.get_daily_visitor_trend(days_count integer DEFAULT 14)
RETURNS TABLE(day text, visitors bigint, views bigint)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH series AS (
    SELECT generate_series(
      (date_trunc('day', now() AT TIME ZONE 'Asia/Kuala_Lumpur') - ((GREATEST(1, LEAST(days_count, 365)) - 1) || ' days')::interval)::date,
      (date_trunc('day', now() AT TIME ZONE 'Asia/Kuala_Lumpur'))::date,
      interval '1 day'
    )::date AS d
  )
  SELECT
    to_char(s.d, 'YYYY-MM-DD') AS day,
    COALESCE(count(DISTINCT pv.visitor_id), 0)::bigint AS visitors,
    COALESCE(count(pv.id), 0)::bigint AS views
  FROM series s
  LEFT JOIN public.page_views pv
    ON (pv.created_at AT TIME ZONE 'Asia/Kuala_Lumpur')::date = s.d
  GROUP BY s.d
  ORDER BY s.d ASC;
$$;

CREATE OR REPLACE FUNCTION public.get_visitor_trend()
RETURNS TABLE(month text, visitors bigint)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH series AS (
    SELECT generate_series(
      date_trunc('month', now() AT TIME ZONE 'Asia/Kuala_Lumpur') - interval '11 months',
      date_trunc('month', now() AT TIME ZONE 'Asia/Kuala_Lumpur'),
      interval '1 month'
    ) AS m
  )
  SELECT
    to_char(s.m, 'YYYY-MM') AS month,
    COALESCE(count(DISTINCT pv.visitor_id), 0)::bigint AS visitors
  FROM series s
  LEFT JOIN public.page_views pv
    ON date_trunc('month', pv.created_at AT TIME ZONE 'Asia/Kuala_Lumpur') = s.m
  GROUP BY s.m
  ORDER BY s.m ASC;
$$;

GRANT EXECUTE ON FUNCTION public.get_daily_visitor_stats() TO anon, authenticated, public;
GRANT EXECUTE ON FUNCTION public.get_visitor_stats() TO anon, authenticated, public;
GRANT EXECUTE ON FUNCTION public.get_daily_visitor_trend(integer) TO anon, authenticated, public;
GRANT EXECUTE ON FUNCTION public.get_visitor_trend() TO anon, authenticated, public;`;
    }

    function buildSingleStorageBucketSql(bucketName) {
        const cleanBucket = String(bucketName || 'property-images').replace(/[^a-z0-9_-]/gi, '') || 'property-images';
        return `INSERT INTO storage.buckets (id, name, public)
VALUES ('${cleanBucket}', '${cleanBucket}', true)
ON CONFLICT (id) DO UPDATE SET public = true;

DROP POLICY IF EXISTS "Public Read ${cleanBucket}" ON storage.objects;
CREATE POLICY "Public Read ${cleanBucket}"
  ON storage.objects FOR SELECT TO public
  USING (bucket_id = '${cleanBucket}');

DROP POLICY IF EXISTS "Public Upload ${cleanBucket}" ON storage.objects;
CREATE POLICY "Public Upload ${cleanBucket}"
  ON storage.objects FOR INSERT TO public
  WITH CHECK (bucket_id = '${cleanBucket}');

DROP POLICY IF EXISTS "Public Update ${cleanBucket}" ON storage.objects;
CREATE POLICY "Public Update ${cleanBucket}"
  ON storage.objects FOR UPDATE TO public
  USING (bucket_id = '${cleanBucket}');

DROP POLICY IF EXISTS "Public Delete ${cleanBucket}" ON storage.objects;
CREATE POLICY "Public Delete ${cleanBucket}"
  ON storage.objects FOR DELETE TO public
  USING (bucket_id = '${cleanBucket}');`;
    }

    function buildCoreCrmTablesSql() {
        const tables = (window.IndustraSupabase && Array.isArray(window.IndustraSupabase.CRM_SCHEMA_TABLES))
            ? window.IndustraSupabase.CRM_SCHEMA_TABLES
            : [];
        const blocks = tables.map((tDef) => {
            const colLines = tDef.columns.map(c => `  ${c.name} ${c.type}`).join(',\n');
            const alterLines = tDef.columns
                .filter(c => !/PRIMARY\s+KEY/i.test(c.type))
                .map(c => {
                    const safeType = c.type.replace(/\bUNIQUE\b/ig, '').replace(/\bNOT\s+NULL\b/ig, '').trim();
                    return `ALTER TABLE public.${tDef.name} ADD COLUMN IF NOT EXISTS ${c.name} ${safeType};`;
                })
                .join('\n');
            return `-- ${tDef.label}: ${tDef.purpose}
CREATE TABLE IF NOT EXISTS public.${tDef.name} (
${colLines}
);
${alterLines}`;
        });

        blocks.push(`-- Ensure unique index on app_users.username for login & upsert onConflict:'username'
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_users_username_unique ON public.app_users (username);
CREATE INDEX IF NOT EXISTS idx_page_views_created_at ON public.page_views (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_page_views_visitor_created ON public.page_views (created_at, visitor_id);

-- Enable Row Level Security & open CRM Data API policies on all 10 tables
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[${tables.map(t => `'${t.name}'`).join(',')}]
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', t);
    EXECUTE format('DROP POLICY IF EXISTS "Allow public full access on %s" ON public.%I;', t, t);
    EXECUTE format('CREATE POLICY "Allow public full access on %s" ON public.%I FOR ALL TO public USING (true) WITH CHECK (true);', t, t);
  END LOOP;
END $$;`);

        return blocks.join('\n\n');
    }

    function buildPrimarySupabaseSetupSql(bucketName, storageOnly = true) {
        const cleanBucket = String(bucketName || 'property-images').replace(/[^a-z0-9_-]/gi, '') || 'property-images';
        const storageSql = buildSingleStorageBucketSql(cleanBucket);

        if (storageOnly) {
            return `-- Run once in your Custom / 2nd Supabase project (SQL Editor)
-- Mode: Storage Bucket Only (keeps PostgreSQL CRM tables on your Built-in Project)

${storageSql}`;
        }

        const extraInsightBucket = cleanBucket !== 'insight-images'
            ? `\n\n${buildSingleStorageBucketSql('insight-images')}`
            : '';

        return `-- Run once in your Fresh / Custom Supabase project (SQL Editor)
-- Mode: Complete CRM Database (10 Tables + 4 Visitor RPCs + Storage Buckets)
-- Tip: Export your .json backup from the old project, then Restore after connecting.

${buildCoreCrmTablesSql()}

${buildVisitorRpcsSql()}

${storageSql}${extraInsightBucket}

NOTIFY pgrst, 'reload schema';`;
    }

    function readPrimarySupabaseFormValues() {
        return {
            enabled: Boolean((document.getElementById('primary-supabase-enabled') || {}).checked),
            storageOnly: Boolean((document.getElementById('primary-supabase-storage-only') || {}).checked),
            url: String((document.getElementById('primary-supabase-url') || {}).value || '').trim().replace(/\/+$/, ''),
            anonKey: String((document.getElementById('primary-supabase-anon-key') || {}).value || '').trim(),
            bucket: String((document.getElementById('primary-supabase-bucket') || {}).value || 'property-images').trim() || 'property-images'
        };
    }

    function setPrimarySupabaseStatusHtml(type, html) {
        const el = document.getElementById('primary-supabase-status');
        if (!el) return;
        const colors = {
            success: '#166534',
            error: '#b91c1c',
            info: '#1d4ed8',
            neutral: '#475569'
        };
        el.style.color = colors[type] || colors.neutral;
        el.innerHTML = html;
    }

    function updatePrimarySupabaseModeHintAndSql() {
        const cfg = readPrimarySupabaseFormValues();
        const hintEl = document.getElementById('primary-supabase-mode-hint');
        const captionEl = document.getElementById('primary-supabase-sql-caption');
        const sqlPre = document.getElementById('primary-supabase-sql-code');

        if (hintEl) {
            hintEl.classList.toggle('is-full-db', !cfg.storageOnly);
            hintEl.innerHTML = cfg.storageOnly
                ? '<i class="fa-solid fa-circle-info" aria-hidden="true"></i><span><strong>Storage Bucket Only (Recommended):</strong> Keeps all CRM tables on your built-in PostgreSQL DB and syncs this custom storage bucket across all browsers automatically.</span>'
                : '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i><span><strong>Full Database + Storage Switch:</strong> Routes both PostgreSQL tables and Storage uploads to the custom project on this browser. Run the Full Setup SQL first, then use <strong>Export / Restore Database (.json)</strong> to migrate records.</span>';
        }
        if (captionEl) {
            captionEl.textContent = cfg.storageOnly
                ? "Run once in your Custom Supabase project's SQL Editor (Storage Bucket Only):"
                : "Run once in your Custom Supabase project's SQL Editor (Full CRM Database + Storage Bucket):";
        }
        if (sqlPre) {
            sqlPre.textContent = buildPrimarySupabaseSetupSql(cfg.bucket, cfg.storageOnly);
        }
    }

    function validatePrimarySupabaseForm(cfg, requireCredentials = true) {
        const inpUrl = document.getElementById('primary-supabase-url');
        const inpKey = document.getElementById('primary-supabase-anon-key');
        const inpBucket = document.getElementById('primary-supabase-bucket');

        [inpUrl, inpKey, inpBucket].forEach(el => {
            if (el) el.removeAttribute('aria-invalid');
        });

        if (!requireCredentials) {
            return { ok: true, firstInvalidEl: null, message: '' };
        }

        if (!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(cfg.url || '')) {
            if (inpUrl) inpUrl.setAttribute('aria-invalid', 'true');
            return {
                ok: false,
                firstInvalidEl: inpUrl,
                message: 'Enter a valid Supabase Project URL (e.g. https://xxxxxxxxxxxx.supabase.co).'
            };
        }
        if (!cfg.anonKey || cfg.anonKey.length < 25) {
            if (inpKey) inpKey.setAttribute('aria-invalid', 'true');
            return {
                ok: false,
                firstInvalidEl: inpKey,
                message: 'Enter the Supabase Anon Public Key (found in Project Settings > API).'
            };
        }
        if (!/^[a-z0-9][a-z0-9_-]{1,62}$/i.test(cfg.bucket || '')) {
            if (inpBucket) inpBucket.setAttribute('aria-invalid', 'true');
            return {
                ok: false,
                firstInvalidEl: inpBucket,
                message: 'Enter a valid Storage Bucket Name using letters, numbers, hyphens, or underscores (e.g. property-images).'
            };
        }
        return { ok: true, firstInvalidEl: null, message: '' };
    }

    window.renderPrimarySupabaseConfigUI = function() {
        const cfg = (window.IndustraSupabase && typeof window.IndustraSupabase.getPrimarySupabaseConfig === 'function')
            ? window.IndustraSupabase.getPrimarySupabaseConfig()
            : { enabled: false, storageOnly: true, url: '', anonKey: '', bucket: 'property-images' };

        const card = document.getElementById('primary-supabase-cloud-card');
        const chkEnabled = document.getElementById('primary-supabase-enabled');
        const chkStorageOnly = document.getElementById('primary-supabase-storage-only');
        const inpUrl = document.getElementById('primary-supabase-url');
        const inpKey = document.getElementById('primary-supabase-anon-key');
        const inpBucket = document.getElementById('primary-supabase-bucket');
        const badge = document.getElementById('primary-supabase-summary-badge');
        const projectLabel = document.getElementById('supabase-active-project-label');

        if (chkEnabled) chkEnabled.checked = Boolean(cfg.enabled);
        if (chkStorageOnly) chkStorageOnly.checked = cfg.storageOnly !== false;
        if (inpUrl) inpUrl.value = cfg.url || '';
        if (inpKey) inpKey.value = cfg.anonKey || '';
        if (inpBucket) inpBucket.value = cfg.bucket || 'property-images';

        const isCustomActive = Boolean(
            cfg.enabled
            && /^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(cfg.url || '')
            && (cfg.anonKey || '').length > 20
        );
        const ref = extractSupabaseProjectRef(cfg.url);

        if (card) card.classList.toggle('is-custom-active', isCustomActive);
        if (badge) {
            if (isCustomActive) {
                badge.textContent = cfg.storageOnly
                    ? `Custom Storage (${cfg.bucket || 'property-images'})`
                    : `Custom Supabase Active (${ref || 'Custom'})`;
                badge.style.background = '#dcfce7';
                badge.style.color = '#166534';
                badge.style.borderColor = '#86efac';
            } else {
                badge.textContent = 'Using Built-in Project';
                badge.style.background = '';
                badge.style.color = '';
                badge.style.borderColor = '';
            }
        }
        if (projectLabel) {
            if (isCustomActive) {
                projectLabel.textContent = cfg.storageOnly
                    ? `Industra + Custom Storage (${ref || cfg.bucket})`
                    : `Custom Project (${ref || cfg.url})`;
            } else {
                projectLabel.textContent = 'Industra';
            }
        }

        updatePrimarySupabaseModeHintAndSql();
    };

    window.testPrimarySupabaseConnectionUI = async function() {
        const cfg = readPrimarySupabaseFormValues();
        updatePrimarySupabaseModeHintAndSql();
        const validation = validatePrimarySupabaseForm(cfg, true);
        if (!validation.ok) {
            setPrimarySupabaseStatusHtml('error', `<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> ${escapeHtml(validation.message)}`);
            if (validation.firstInvalidEl) validation.firstInvalidEl.focus();
            return;
        }

        const btn = document.getElementById('btn-test-primary-supabase');
        const origHtml = btn ? btn.innerHTML : '';
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Testing...';
        }
        setPrimarySupabaseStatusHtml('info', '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Testing connection to custom Supabase project...');

        try {
            if (!window.IndustraSupabase || typeof window.IndustraSupabase.testPrimarySupabaseConnection !== 'function') {
                setPrimarySupabaseStatusHtml('error', 'Supabase helper is not ready yet.');
                return;
            }
            const res = await window.IndustraSupabase.testPrimarySupabaseConnection(cfg);
            if (res && res.ok) {
                setPrimarySupabaseStatusHtml('success', `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> ${escapeHtml(res.message)}`);
            } else {
                setPrimarySupabaseStatusHtml('error', `<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> ${escapeHtml((res && res.message) || 'Connection test failed. Run the Setup SQL below in your Supabase project first.')}`);
            }
        } finally {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = origHtml;
            }
        }
    };

    window.savePrimarySupabaseConfigUI = async function(event) {
        if (event && typeof event.preventDefault === 'function') event.preventDefault();
        const cfg = readPrimarySupabaseFormValues();
        const validation = validatePrimarySupabaseForm(cfg, cfg.enabled);
        if (!validation.ok) {
            setPrimarySupabaseStatusHtml('error', `<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> ${escapeHtml(validation.message)}`);
            if (validation.firstInvalidEl) validation.firstInvalidEl.focus();
            return;
        }

        const saveBtn = document.getElementById('btn-save-primary-supabase');
        const origHtml = saveBtn ? saveBtn.innerHTML : '';
        if (saveBtn) {
            saveBtn.disabled = true;
            saveBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Saving...';
        }

        try {
            settings.primarySupabaseCloud = cfg;
            window.__liveSiteSettings = settings;
            safeLocalStorageSet('industria_settings', settings);

            // When switching Full DB to a custom project, also best-effort publish the routing pointer
            // to the built-in default DB so fresh browsers on other devices can discover the active DB.
            if (cfg.enabled && !cfg.storageOnly && window.IndustraSupabase && typeof window.IndustraSupabase.upsertSiteSettingToBuiltIn === 'function') {
                try {
                    await window.IndustraSupabase.upsertSiteSettingToBuiltIn('general_settings', settings);
                } catch (_) {}
            }

            if (window.IndustraSupabase && typeof window.IndustraSupabase.setPrimarySupabaseConfig === 'function') {
                window.IndustraSupabase.setPrimarySupabaseConfig(cfg);
            }

            try {
                await saveGeneralSettingsToSupabase();
            } catch (syncErr) {
                console.warn('Notice saving primarySupabaseCloud to site_settings:', syncErr);
            }

            window.renderPrimarySupabaseConfigUI();
            if (typeof window.renderMediaStorageConfigUI === 'function') {
                window.renderMediaStorageConfigUI();
            }
            if (typeof window.checkSupabaseStorageUsage === 'function') {
                await window.checkSupabaseStorageUsage();
            }

            if (typeof window.logDashboardActivity === 'function') {
                window.logDashboardActivity({
                    category: 'Settings',
                    action: cfg.enabled ? 'Connect Custom Supabase' : 'Use Built-in Supabase',
                    target: cfg.enabled ? `${cfg.url} (${cfg.bucket})` : 'Built-in Industra Supabase',
                    details: cfg.enabled
                        ? (cfg.storageOnly ? 'Enabled custom Supabase Storage Bucket Only mode' : 'Enabled custom Supabase Full DB + Storage mode')
                        : 'Reverted primary Supabase routing to built-in project'
                });
            }

            const vercelTipHtml = (cfg.enabled && !cfg.storageOnly)
                ? `<div style="margin-top:0.5rem;padding:0.55rem 0.75rem;border-radius:8px;background:#eff6ff;border:1px solid #bfdbfe;color:#1e3a8a;font-size:0.8rem;line-height:1.45;"><strong>Vercel / Multi-Device Tip:</strong> Browser settings only apply automatically on this device. To ensure <em>all other computers &amp; mobile visitors</em> load this database immediately on Vercel, add <code>SUPABASE_URL</code> and <code>SUPABASE_ANON_KEY</code> in <strong>Vercel &rarr; Project Settings &rarr; Environment Variables</strong> (and redeploy), or update the built-in defaults in <code>js/supabase-client.js</code>.</div>`
                : '';

            setPrimarySupabaseStatusHtml(
                'success',
                cfg.enabled
                    ? `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> Saved &amp; connected! ${cfg.storageOnly ? 'Storage bucket' : 'Database &amp; storage bucket'} now points to <strong>${escapeHtml(cfg.url)}</strong> (bucket: <code>${escapeHtml(cfg.bucket)}</code>).${vercelTipHtml}`
                    : '<i class="fa-solid fa-circle-info" aria-hidden="true"></i> Saved! Reverted to the built-in Industra Supabase project (bucket: <code>property-images</code>).'
            );
            if (typeof showToast === 'function') {
                showToast(
                    cfg.enabled
                        ? (cfg.storageOnly ? `Switched image storage to ${cfg.bucket}!` : 'Connected to custom Supabase project!')
                        : 'Reverted to built-in Supabase project.',
                    'success'
                );
            }
        } finally {
            if (saveBtn) {
                saveBtn.disabled = false;
                saveBtn.innerHTML = origHtml;
            }
        }
    };

    window.resetPrimarySupabaseConfigUI = async function() {
        const current = (window.IndustraSupabase && typeof window.IndustraSupabase.getPrimarySupabaseConfig === 'function')
            ? window.IndustraSupabase.getPrimarySupabaseConfig()
            : null;
        if (current && current.enabled) {
            const ok = confirm('Reset Primary Supabase Account settings back to the built-in Industra project (property-images)?');
            if (!ok) return;
        }
        if (window.IndustraSupabase && typeof window.IndustraSupabase.resetPrimarySupabaseConfig === 'function') {
            window.IndustraSupabase.resetPrimarySupabaseConfig();
        }
        settings.primarySupabaseCloud = null;
        window.__liveSiteSettings = settings;
        safeLocalStorageSet('industria_settings', settings);
        try {
            await saveGeneralSettingsToSupabase();
        } catch (_) {}

        ['primary-supabase-url', 'primary-supabase-anon-key', 'primary-supabase-bucket'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.removeAttribute('aria-invalid');
        });

        window.renderPrimarySupabaseConfigUI();
        if (typeof window.renderMediaStorageConfigUI === 'function') {
            window.renderMediaStorageConfigUI();
        }
        if (typeof window.checkSupabaseStorageUsage === 'function') {
            await window.checkSupabaseStorageUsage();
        }
        setPrimarySupabaseStatusHtml('info', '<i class="fa-solid fa-rotate-left" aria-hidden="true"></i> Reset to built-in Industra Supabase project (<code>property-images</code>).');
        if (typeof showToast === 'function') {
            showToast('Reset to built-in Supabase configuration.', 'info');
        }
    };

    window.togglePrimarySupabaseSetupSql = function() {
        const wrap = document.getElementById('primary-supabase-sql-wrap');
        const toggleBtn = document.getElementById('btn-toggle-primary-supabase-sql');
        if (!wrap) return;
        updatePrimarySupabaseModeHintAndSql();
        const willOpen = wrap.hidden;
        wrap.hidden = !willOpen;
        if (toggleBtn) toggleBtn.setAttribute('aria-expanded', String(willOpen));
    };

    // Accessible Copy SQL handler using Invoker Commands (with non-duplicate click fallback)
    const primarySqlCopyTimers = new WeakMap();
    let lastPrimarySqlCopyMessage = '';

    function legacyCopyTextFallback(text) {
        const previousFocus = document.activeElement;
        const field = Object.assign(document.createElement('textarea'), { value: text });
        field.setAttribute('readonly', '');
        field.style.cssText = 'position:fixed;inset-block-start:0;opacity:0';
        document.body.append(field);
        field.select();
        try {
            return document.execCommand('copy');
        } finally {
            field.remove();
            if (previousFocus && typeof previousFocus.focus === 'function') {
                previousFocus.focus({ preventScroll: true });
            }
        }
    }

    function reportPrimarySqlCopyFeedback(button, ok) {
        if (!button) return;
        const tip = button.nextElementSibling;
        clearTimeout(primarySqlCopyTimers.get(button));
        button.removeAttribute('data-copied');
        button.removeAttribute('data-failed');
        let message = ok ? 'Copied' : 'Copy failed';
        if (message === lastPrimarySqlCopyMessage) message += '\u00A0';
        lastPrimarySqlCopyMessage = message;
        if (tip) tip.textContent = '';
        void button.offsetWidth;
        button.setAttribute(ok ? 'data-copied' : 'data-failed', '');
        requestAnimationFrame(() => {
            if (tip) tip.textContent = message;
        });
        primarySqlCopyTimers.set(button, setTimeout(() => {
            button.removeAttribute('data-copied');
            button.removeAttribute('data-failed');
            if (tip) tip.textContent = '';
        }, 2000));
    }

    async function copyPrimarySqlTarget(button, target) {
        if (!target) return;
        updatePrimarySupabaseModeHintAndSql();
        const text = target.matches('input, textarea')
            ? target.value
            : (target.innerText || target.textContent || '').trim();
        if (!text) return;
        try {
            if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
                await navigator.clipboard.writeText(text);
            } else if (!legacyCopyTextFallback(text)) {
                throw new Error('Copy failed');
            }
            reportPrimarySqlCopyFeedback(button, true);
            if (typeof showToast === 'function') {
                showToast('Setup SQL copied! Paste into your Supabase SQL Editor.', 'success');
            }
        } catch (_) {
            try {
                if (legacyCopyTextFallback(text)) {
                    reportPrimarySqlCopyFeedback(button, true);
                    if (typeof showToast === 'function') {
                        showToast('Setup SQL copied! Paste into your Supabase SQL Editor.', 'success');
                    }
                    return;
                }
            } catch (_) {}
            reportPrimarySqlCopyFeedback(button, false);
        }
    }

    function initPrimarySupabaseConfigUI() {
        const form = document.getElementById('primary-supabase-cloud-form');
        if (!form || form.dataset.wired === 'true') return;
        form.dataset.wired = 'true';

        form.addEventListener('submit', window.savePrimarySupabaseConfigUI);

        const testBtn = document.getElementById('btn-test-primary-supabase');
        if (testBtn) testBtn.addEventListener('click', window.testPrimarySupabaseConnectionUI);

        const resetBtn = document.getElementById('btn-reset-primary-supabase');
        if (resetBtn) resetBtn.addEventListener('click', window.resetPrimarySupabaseConfigUI);

        const toggleSqlBtn = document.getElementById('btn-toggle-primary-supabase-sql');
        if (toggleSqlBtn) toggleSqlBtn.addEventListener('click', window.togglePrimarySupabaseSetupSql);

        const storageOnlyChk = document.getElementById('primary-supabase-storage-only');
        if (storageOnlyChk) storageOnlyChk.addEventListener('change', updatePrimarySupabaseModeHintAndSql);

        const inpUrl = document.getElementById('primary-supabase-url');
        const inpKey = document.getElementById('primary-supabase-anon-key');
        const inpBucket = document.getElementById('primary-supabase-bucket');

        [inpUrl, inpKey, inpBucket].forEach((el) => {
            if (!el) return;
            el.addEventListener('input', () => {
                el.removeAttribute('aria-invalid');
                if (el === inpBucket) updatePrimarySupabaseModeHintAndSql();
            });
            el.addEventListener('blur', () => {
                const cfg = readPrimarySupabaseFormValues();
                if (!cfg.enabled || !el.value.trim()) return;
                if (el === inpUrl && !/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(cfg.url)) {
                    el.setAttribute('aria-invalid', 'true');
                } else if (el === inpKey && cfg.anonKey.length < 25) {
                    el.setAttribute('aria-invalid', 'true');
                } else if (el === inpBucket && !/^[a-z0-9][a-z0-9_-]{1,62}$/i.test(cfg.bucket)) {
                    el.setAttribute('aria-invalid', 'true');
                }
            });
        });

        const toggleKeyBtn = document.getElementById('primary-supabase-toggle-key');
        if (toggleKeyBtn && inpKey) {
            toggleKeyBtn.addEventListener('click', () => {
                const showing = inpKey.type === 'text';
                inpKey.type = showing ? 'password' : 'text';
                toggleKeyBtn.setAttribute('aria-pressed', String(!showing));
                toggleKeyBtn.setAttribute('aria-label', showing ? 'Show Supabase Anon Public Key' : 'Hide Supabase Anon Public Key');
                const icon = toggleKeyBtn.querySelector('i');
                if (icon) {
                    icon.classList.toggle('fa-eye', showing);
                    icon.classList.toggle('fa-eye-slash', !showing);
                }
            });
        }

        if ('CommandEvent' in window) {
            document.addEventListener('command', (event) => {
                if (event.command === '--copy' && event.target && (event.target.id === 'primary-supabase-sql-code' || event.target.id === 'schema-builder-sql-code')) {
                    copyPrimarySqlTarget(event.source, event.target);
                }
            }, true);
        } else {
            document.addEventListener('click', (event) => {
                if (event.defaultPrevented) return;
                const button = event.target.closest('button[command="--copy"][commandfor="primary-supabase-sql-code"], button[command="--copy"][commandfor="schema-builder-sql-code"]');
                if (!button) return;
                const target = document.getElementById(button.getAttribute('commandfor'));
                if (target) copyPrimarySqlTarget(button, target);
            });
        }

        window.renderPrimarySupabaseConfigUI();
    }

    initPrimarySupabaseConfigUI();

    // =========================================================================
    // 1-CLICK DATABASE SCHEMA PROVISIONER & VISUAL TABLE / COLUMN BUILDER
    // =========================================================================
    const SAFE_PG_IDENT_RE = /^[a-z_][a-z0-9_]{0,62}$/;
    const ALLOWED_PG_TYPES = new Set([
        'text', 'integer', 'bigint', 'numeric', 'double precision',
        'boolean', 'jsonb', 'timestamptz', 'date', 'uuid'
    ]);
    const customSchemaQueue = [];

    function sanitizePgIdent(raw) {
        return String(raw || '').trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '').replace(/^[0-9]/, '_$&').slice(0, 63);
    }

    function sanitizePgDefault(rawDefault, dataType) {
        const val = String(rawDefault || '').trim();
        if (!val) return '';
        if (/^(now\(\)|true|false|null|gen_random_uuid\(\)|'\{\}'::jsonb|'\[\]'::jsonb)$/i.test(val)) {
            return val;
        }
        if ((dataType === 'integer' || dataType === 'bigint' || dataType === 'numeric' || dataType === 'double precision') && /^-?\d+(\.\d+)?$/.test(val)) {
            return val;
        }
        if (dataType === 'boolean' && /^(true|false)$/i.test(val)) {
            return val.toLowerCase();
        }
        const stripped = val.replace(/^'(.*)'$/, '$1').replace(/'/g, "''");
        return `'${stripped}'`;
    }

    function setSchemaBuilderStatusHtml(type, html) {
        const el = document.getElementById('schema-builder-status');
        if (!el) return;
        const colors = { success: '#166534', error: '#b91c1c', info: '#1d4ed8', neutral: '#475569' };
        el.style.color = colors[type] || colors.neutral;
        el.innerHTML = html;
    }

    function getActiveSchemaTargetRef() {
        const formCfg = readPrimarySupabaseFormValues();
        if (formCfg && formCfg.url && /^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(formCfg.url) && formCfg.enabled && !formCfg.storageOnly) {
            return { ref: extractSupabaseProjectRef(formCfg.url), url: formCfg.url, bucket: formCfg.bucket || 'property-images', overrideCfg: formCfg };
        }
        const activeUrl = (window.IndustraSupabase && typeof window.IndustraSupabase.getActiveDbUrl === 'function')
            ? window.IndustraSupabase.getActiveDbUrl()
            : '';
        const bucket = (window.IndustraSupabase && typeof window.IndustraSupabase.getPrimaryBucketName === 'function')
            ? window.IndustraSupabase.getPrimaryBucketName()
            : 'property-images';
        return { ref: extractSupabaseProjectRef(activeUrl), url: activeUrl, bucket, overrideCfg: null };
    }

    function createSchemaColRowEl(initial = {}) {
        const row = document.createElement('div');
        row.className = 'schema-col-row';
        row.innerHTML = `
            <input type="text" class="form-control schema-col-name-inp" placeholder="column_name (e.g. escalation_note)" value="${escapeHtml(initial.name || '')}" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" aria-label="Column Name">
            <select class="form-control schema-col-type-sel" aria-label="Data Type">
                <option value="text">text (String)</option>
                <option value="integer">integer (Whole #)</option>
                <option value="numeric">numeric (Decimal / Price)</option>
                <option value="boolean">boolean (True/False)</option>
                <option value="jsonb">jsonb (JSON Object/Array)</option>
                <option value="timestamptz">timestamptz (Date &amp; Time)</option>
                <option value="date">date (YYYY-MM-DD)</option>
                <option value="uuid">uuid</option>
            </select>
            <input type="text" class="form-control schema-col-default-inp" placeholder="Default (optional)" value="${escapeHtml(initial.defaultVal || '')}" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" aria-label="Default Value">
            <label class="schema-col-notnull">
                <input type="checkbox" class="schema-col-notnull-chk" ${initial.notNull ? 'checked' : ''}>
                <span>Not Null</span>
            </label>
            <button type="button" class="action-btn delete schema-col-remove-btn" title="Remove column row" aria-label="Remove column">
                <i class="fa-solid fa-trash" aria-hidden="true"></i>
            </button>
        `;
        const typeSel = row.querySelector('.schema-col-type-sel');
        if (typeSel && initial.type) typeSel.value = initial.type;
        row.querySelector('.schema-col-remove-btn').addEventListener('click', () => {
            const list = document.getElementById('schema-custom-columns-list');
            row.remove();
            if (list && list.children.length === 0) {
                list.appendChild(createSchemaColRowEl());
            }
            refreshSchemaBuilderSqlPreview();
        });
        row.querySelectorAll('input, select').forEach(el => {
            el.addEventListener('input', refreshSchemaBuilderSqlPreview);
            el.addEventListener('change', refreshSchemaBuilderSqlPreview);
        });
        return row;
    }

    function readDraftCustomDesignerOperation() {
        const mode = (document.getElementById('schema-custom-mode') || {}).value || 'add_columns';
        const tableRaw = mode === 'create_table'
            ? ((document.getElementById('schema-new-table-name') || {}).value || '')
            : ((document.getElementById('schema-existing-table-select') || {}).value || '');
        const tableName = sanitizePgIdent(tableRaw);
        const list = document.getElementById('schema-custom-columns-list');
        const cols = [];
        if (list) {
            list.querySelectorAll('.schema-col-row').forEach(row => {
                const rawName = (row.querySelector('.schema-col-name-inp') || {}).value || '';
                const colName = sanitizePgIdent(rawName);
                const colType = (row.querySelector('.schema-col-type-sel') || {}).value || 'text';
                const defVal = (row.querySelector('.schema-col-default-inp') || {}).value || '';
                const notNull = Boolean((row.querySelector('.schema-col-notnull-chk') || {}).checked);
                if (colName && SAFE_PG_IDENT_RE.test(colName) && ALLOWED_PG_TYPES.has(colType)) {
                    cols.push({ name: colName, type: colType, defaultVal: defVal.trim(), notNull });
                }
            });
        }
        return { mode, tableName, columns: cols };
    }

    function buildCustomOperationSql(op) {
        if (!op || !op.tableName || !SAFE_PG_IDENT_RE.test(op.tableName)) return '';
        const tName = op.tableName;
        if (op.mode === 'create_table') {
            const extraCols = (op.columns || []).filter(c => c.name !== 'id' && c.name !== 'created_at');
            const colDefs = [
                '  id text PRIMARY KEY DEFAULT gen_random_uuid()::text',
                ...extraCols.map(c => {
                    const defExpr = sanitizePgDefault(c.defaultVal, c.type);
                    return `  ${c.name} ${c.type}${c.notNull ? ' NOT NULL' : ''}${defExpr ? ` DEFAULT ${defExpr}` : ''}`;
                }),
                '  created_at timestamptz DEFAULT now()'
            ];
            return `-- Custom Table: public.${tName}
CREATE TABLE IF NOT EXISTS public.${tName} (
${colDefs.join(',\n')}
);
ALTER TABLE public.${tName} ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public full access on ${tName}" ON public.${tName};
CREATE POLICY "Allow public full access on ${tName}"
  ON public.${tName} FOR ALL TO public
  USING (true) WITH CHECK (true);`;
        }
        if (!op.columns || op.columns.length === 0) return '';
        const alters = op.columns.map(c => {
            const defExpr = sanitizePgDefault(c.defaultVal, c.type);
            // Only apply NOT NULL on ADD COLUMN when a DEFAULT is supplied (safe on populated tables)
            const nnClause = (c.notNull && defExpr) ? ' NOT NULL' : '';
            return `ALTER TABLE public.${tName} ADD COLUMN IF NOT EXISTS ${c.name} ${c.type}${defExpr ? ` DEFAULT ${defExpr}` : ''}${nnClause};`;
        });
        return `-- Custom Column(s) on public.${tName}\n${alters.join('\n')}`;
    }

    function buildCompleteSchemaBuilderSql() {
        const incTables = Boolean((document.getElementById('schema-inc-core-tables') || {}).checked);
        const incRpcs = Boolean((document.getElementById('schema-inc-visitor-rpcs') || {}).checked);
        const incBuckets = Boolean((document.getElementById('schema-inc-buckets') || {}).checked);
        const incSeedAdmin = Boolean((document.getElementById('schema-inc-seed-admin') || {}).checked);

        const target = getActiveSchemaTargetRef();
        const primaryBucket = String(target.bucket || 'property-images').replace(/[^a-z0-9_-]/gi, '') || 'property-images';
        const parts = [
            `-- Industra / MyFactorySpace CRM Database Schema Script`,
            `-- Target Project: ${target.url || 'Active Supabase Project'} | Safe to re-run (idempotent)`
        ];

        if (incTables) {
            parts.push(buildCoreCrmTablesSql());
        }
        if (incRpcs) {
            parts.push(buildVisitorRpcsSql());
        }
        if (incBuckets) {
            parts.push(buildSingleStorageBucketSql(primaryBucket));
            if (primaryBucket !== 'insight-images') {
                parts.push(buildSingleStorageBucketSql('insight-images'));
            }
        }
        if (incSeedAdmin) {
            parts.push(`-- Seed default CRM Administrator login if not already created
INSERT INTO public.app_users (id, username, password, role, specs)
VALUES ('usr_admin_default', 'admin', 'admin123', 'Administrator', '{"username":"admin","role":"Administrator","fullName":"Administrator"}'::jsonb)
ON CONFLICT (username) DO NOTHING;`);
        }

        // Queued custom operations + active draft (if filled)
        const allOps = [...customSchemaQueue];
        const draft = readDraftCustomDesignerOperation();
        if (draft.tableName && (draft.mode === 'create_table' || draft.columns.length > 0)) {
            allOps.push(draft);
        }
        allOps.forEach(op => {
            const sqlPart = buildCustomOperationSql(op);
            if (sqlPart) parts.push(sqlPart);
        });

        parts.push(`NOTIFY pgrst, 'reload schema';`);
        return parts.join('\n\n');
    }

    function refreshSchemaBuilderSqlPreview() {
        const sqlPre = document.getElementById('schema-builder-sql-code');
        if (sqlPre) sqlPre.textContent = buildCompleteSchemaBuilderSql();
    }

    function renderCustomSchemaQueueUI() {
        const container = document.getElementById('schema-custom-queue');
        if (!container) return;
        if (customSchemaQueue.length === 0) {
            container.innerHTML = '';
            refreshSchemaBuilderSqlPreview();
            return;
        }
        container.innerHTML = customSchemaQueue.map((op, idx) => {
            const desc = op.mode === 'create_table'
                ? `CREATE TABLE ${op.tableName} (${op.columns.length + 2} cols)`
                : `ALTER ${op.tableName} (+${op.columns.map(c => c.name).join(', ')})`;
            return `<span class="schema-queue-chip"><i class="fa-solid fa-table" aria-hidden="true"></i><span>${escapeHtml(desc)}</span><button type="button" data-remove-idx="${idx}" aria-label="Remove queued change">&times;</button></span>`;
        }).join('');
        container.querySelectorAll('button[data-remove-idx]').forEach(btn => {
            btn.addEventListener('click', () => {
                const idx = parseInt(btn.getAttribute('data-remove-idx'), 10);
                if (Number.isFinite(idx)) customSchemaQueue.splice(idx, 1);
                renderCustomSchemaQueueUI();
            });
        });
        refreshSchemaBuilderSqlPreview();
    }

    function renderSchemaHealthGrid(scanResult = null) {
        const grid = document.getElementById('schema-health-grid');
        const badge = document.getElementById('schema-builder-summary-badge');
        if (!grid) return;

        const manifestTables = (window.IndustraSupabase && Array.isArray(window.IndustraSupabase.CRM_SCHEMA_TABLES))
            ? window.IndustraSupabase.CRM_SCHEMA_TABLES
            : [];
        const manifestRpcs = (window.IndustraSupabase && Array.isArray(window.IndustraSupabase.CRM_SCHEMA_RPCS))
            ? window.IndustraSupabase.CRM_SCHEMA_RPCS
            : [];

        if (!scanResult) {
            const target = getActiveSchemaTargetRef();
            const items = [
                ...manifestTables.map(t => `
                    <div class="schema-health-item" title="${escapeHtml(t.purpose)}">
                        <div style="min-inline-size:0;">
                            <div class="schema-health-name">${escapeHtml(t.name)}</div>
                            <span class="schema-health-meta">${t.columns.length} cols &bull; ${escapeHtml(t.label)}</span>
                        </div>
                        <span class="schema-health-pill is-idle">Required</span>
                    </div>`),
                `<div class="schema-health-item" title="4 PostgreSQL functions for Overview visitor KPIs & daily/monthly traffic charts">
                    <div style="min-inline-size:0;">
                        <div class="schema-health-name">4 Visitor RPCs</div>
                        <span class="schema-health-meta">Overview charts &amp; KPIs</span>
                    </div>
                    <span class="schema-health-pill is-idle">Required</span>
                </div>`,
                `<div class="schema-health-item" title="Public media storage bucket for listings, parks, agents & branding">
                    <div style="min-inline-size:0;">
                        <div class="schema-health-name">${escapeHtml(target.bucket || 'property-images')}</div>
                        <span class="schema-health-meta">Public Storage Bucket</span>
                    </div>
                    <span class="schema-health-pill is-idle">Storage</span>
                </div>`
            ];
            grid.innerHTML = items.join('');
            return;
        }

        const tiles = [];
        (scanResult.tables || []).forEach(t => {
            const isReady = t.status === 'ready';
            const isWarn = t.status === 'missing_columns';
            const cls = isReady ? 'is-ready' : (isWarn ? 'is-warn' : 'is-missing');
            const pillText = isReady ? 'Ready' : (isWarn ? `${t.missingColumns.length} Missing Col` : 'Missing');
            const metaText = isWarn
                ? `Missing: ${t.missingColumns.join(', ')}`
                : `${t.columnCount} cols • ${t.label}`;
            tiles.push(`
                <div class="schema-health-item ${cls}" title="${escapeHtml(t.error || metaText)}">
                    <div style="min-inline-size:0;">
                        <div class="schema-health-name">${escapeHtml(t.name)}</div>
                        <span class="schema-health-meta">${escapeHtml(metaText)}</span>
                    </div>
                    <span class="schema-health-pill ${cls}">${pillText}</span>
                </div>`);
        });

        const readyRpcs = scanResult.readyRpcs || 0;
        const totalRpcs = scanResult.totalRpcs || manifestRpcs.length;
        const rpcCls = readyRpcs === totalRpcs ? 'is-ready' : (readyRpcs > 0 ? 'is-warn' : 'is-missing');
        tiles.push(`
            <div class="schema-health-item ${rpcCls}" title="Daily/Monthly visitor stats & chart RPCs">
                <div style="min-inline-size:0;">
                    <div class="schema-health-name">Visitor RPCs</div>
                    <span class="schema-health-meta">${readyRpcs} / ${totalRpcs} analytics functions</span>
                </div>
                <span class="schema-health-pill ${rpcCls}">${readyRpcs === totalRpcs ? 'Ready' : `${totalRpcs - readyRpcs} Missing`}</span>
            </div>`);

        (scanResult.buckets || []).forEach(b => {
            const bCls = b.status === 'ready' ? 'is-ready' : 'is-missing';
            tiles.push(`
                <div class="schema-health-item ${bCls}" title="${escapeHtml(b.error || `Storage bucket ${b.name}`)}">
                    <div style="min-inline-size:0;">
                        <div class="schema-health-name">${escapeHtml(b.name)}</div>
                        <span class="schema-health-meta">Storage Bucket</span>
                    </div>
                    <span class="schema-health-pill ${bCls}">${b.status === 'ready' ? 'Ready' : 'Missing'}</span>
                </div>`);
        });

        grid.innerHTML = tiles.join('');

        if (badge) {
            if (scanResult.ok) {
                badge.textContent = `All ${scanResult.totalTables} Tables + ${totalRpcs} RPCs Ready`;
                badge.style.background = '#dcfce7';
                badge.style.color = '#166534';
                badge.style.borderColor = '#86efac';
            } else {
                const missingTables = (scanResult.totalTables || 0) - (scanResult.readyTables || 0);
                badge.textContent = `${scanResult.readyTables}/${scanResult.totalTables} Tables Ready (${missingTables} Pending)`;
                badge.style.background = '#fef3c7';
                badge.style.color = '#92400e';
                badge.style.borderColor = '#fde68a';
            }
        }
    }

    window.scanCrmDatabaseSchemaUI = async function() {
        const btn = document.getElementById('btn-scan-crm-schema');
        const origHtml = btn ? btn.innerHTML : '';
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Scanning...';
        }
        setSchemaBuilderStatusHtml('info', '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Scanning all 10 required CRM tables, columns, 4 visitor RPCs, and storage buckets...');
        try {
            if (!window.IndustraSupabase || typeof window.IndustraSupabase.inspectCrmDatabaseSchema !== 'function') {
                setSchemaBuilderStatusHtml('error', 'Supabase helper is not ready yet.');
                return;
            }
            const target = getActiveSchemaTargetRef();
            const res = await window.IndustraSupabase.inspectCrmDatabaseSchema(target.overrideCfg);
            renderSchemaHealthGrid(res);
            if (res && res.ok) {
                setSchemaBuilderStatusHtml('success', `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> Verified! All <strong>${res.totalTables}</strong> CRM tables, <strong>${res.totalRpcs}</strong> visitor RPCs, and storage bucket are ready on <code>${escapeHtml(res.projectRef || target.url)}</code>.`);
            } else if (res) {
                setSchemaBuilderStatusHtml('info', `<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Found <strong>${res.readyTables}/${res.totalTables}</strong> tables and <strong>${res.readyRpcs}/${res.totalRpcs}</strong> visitor RPCs ready on <code>${escapeHtml(res.projectRef || target.url)}</code>. Click <strong>Create Tables &amp; Columns Now (1-Click)</strong> or <strong>Copy SQL &amp; Open Supabase SQL Editor</strong> to provision everything missing.`);
            }
        } finally {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = origHtml;
            }
        }
    };

    window.runCrmSchemaProvisioningUI = async function() {
        const sql = buildCompleteSchemaBuilderSql();
        refreshSchemaBuilderSqlPreview();
        const target = getActiveSchemaTargetRef();
        if (!target.ref) {
            setSchemaBuilderStatusHtml('error', '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Could not resolve a valid Supabase Project Reference ID. Enter your Project URL in <strong>Custom Supabase Account</strong> above first.');
            return;
        }

        const patInput = document.getElementById('schema-mgmt-pat');
        const pat = patInput ? patInput.value.trim() : '';
        if (pat) {
            try { sessionStorage.setItem('industria_sb_mgmt_pat', pat); } catch (_) {}
        }

        const runBtn = document.getElementById('btn-run-crm-schema');
        const origHtml = runBtn ? runBtn.innerHTML : '';
        if (runBtn) {
            runBtn.disabled = true;
            runBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Creating Tables &amp; Columns...';
        }
        setSchemaBuilderStatusHtml('info', `<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Provisioning schema on Supabase project <code>${escapeHtml(target.ref)}</code>...`);

        try {
            const res = await window.IndustraSupabase.executeSchemaViaApi({
                projectRef: target.ref,
                sql,
                accessToken: pat
            });
            if (res && res.ok) {
                customSchemaQueue.length = 0;
                renderCustomSchemaQueueUI();
                setSchemaBuilderStatusHtml('success', `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> ${escapeHtml(res.message || 'Tables & columns created successfully!')} Re-scanning live schema...`);
                if (typeof showToast === 'function') showToast('Supabase tables & columns created!', 'success');
                if (typeof window.logDashboardActivity === 'function') {
                    window.logDashboardActivity({
                        category: 'Settings',
                        action: 'Provision Schema',
                        target: `Supabase (${target.ref})`,
                        details: 'Provisioned CRM tables, RPCs, storage buckets & custom columns via 1-Click Schema Builder'
                    });
                }
                setTimeout(() => {
                    window.scanCrmDatabaseSchemaUI();
                    if (typeof window.checkSupabaseStorageUsage === 'function') window.checkSupabaseStorageUsage();
                }, 800);
            } else {
                const errText = (res && res.error) ? res.error : 'Direct API execution unavailable.';
                setSchemaBuilderStatusHtml(
                    'error',
                    `<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> ${escapeHtml(errText)} — <strong>Tip:</strong> Click <strong>Copy SQL &amp; Open Supabase SQL Editor</strong> to run the exact script in 2 seconds.`
                );
            }
        } finally {
            if (runBtn) {
                runBtn.disabled = false;
                runBtn.innerHTML = origHtml;
            }
        }
    };

    window.copyAndOpenSupabaseSqlEditorUI = async function() {
        const sql = buildCompleteSchemaBuilderSql();
        refreshSchemaBuilderSqlPreview();
        let copied = false;
        try {
            if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
                await navigator.clipboard.writeText(sql);
                copied = true;
            }
        } catch (_) {}
        if (!copied) {
            copied = legacyCopyTextFallback(sql);
        }
        const target = getActiveSchemaTargetRef();
        const editorUrl = target.ref
            ? `https://supabase.com/dashboard/project/${encodeURIComponent(target.ref)}/sql/new`
            : 'https://supabase.com/dashboard/projects';
        window.open(editorUrl, '_blank', 'noopener,noreferrer');

        setSchemaBuilderStatusHtml(
            'success',
            `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> ${copied ? 'Complete SQL copied to clipboard and ' : ''}opened <strong>Supabase SQL Editor</strong> for <code>${escapeHtml(target.ref || 'your project')}</code>. Press <strong>Cmd+V / Ctrl+V</strong> &rarr; <strong>Run</strong>, then click <strong>Scan Database Schema</strong> to confirm all green!`
        );
        if (typeof showToast === 'function') {
            showToast('SQL copied! Paste and click Run in Supabase SQL Editor.', 'success');
        }
    };

    function initCrmSchemaBuilderUI() {
        const card = document.getElementById('supabase-schema-builder-card');
        if (!card || card.dataset.wired === 'true') return;
        card.dataset.wired = 'true';

        const colsList = document.getElementById('schema-custom-columns-list');
        if (colsList && colsList.children.length === 0) {
            colsList.appendChild(createSchemaColRowEl());
        }

        const patInput = document.getElementById('schema-mgmt-pat');
        if (patInput) {
            try {
                const savedPat = sessionStorage.getItem('industria_sb_mgmt_pat');
                if (savedPat) patInput.value = savedPat;
            } catch (_) {}
            patInput.addEventListener('change', () => {
                try {
                    const v = patInput.value.trim();
                    if (v) sessionStorage.setItem('industria_sb_mgmt_pat', v);
                    else sessionStorage.removeItem('industria_sb_mgmt_pat');
                } catch (_) {}
            });
        }

        const togglePatBtn = document.getElementById('btn-toggle-schema-pat');
        if (togglePatBtn && patInput) {
            togglePatBtn.addEventListener('click', () => {
                const showing = patInput.type === 'text';
                patInput.type = showing ? 'password' : 'text';
                togglePatBtn.setAttribute('aria-pressed', String(!showing));
                togglePatBtn.setAttribute('aria-label', showing ? 'Show Personal Access Token' : 'Hide Personal Access Token');
                const icon = togglePatBtn.querySelector('i');
                if (icon) {
                    icon.classList.toggle('fa-eye', showing);
                    icon.classList.toggle('fa-eye-slash', !showing);
                }
            });
        }

        const modeSel = document.getElementById('schema-custom-mode');
        const existWrap = document.getElementById('schema-existing-table-wrap');
        const newWrap = document.getElementById('schema-new-table-wrap');
        if (modeSel) {
            modeSel.addEventListener('change', () => {
                const isNew = modeSel.value === 'create_table';
                if (existWrap) existWrap.style.display = isNew ? 'none' : '';
                if (newWrap) newWrap.style.display = isNew ? '' : 'none';
                refreshSchemaBuilderSqlPreview();
            });
        }

        ['schema-inc-core-tables', 'schema-inc-visitor-rpcs', 'schema-inc-buckets', 'schema-inc-seed-admin', 'schema-existing-table-select', 'schema-new-table-name'].forEach(id => {
            const el = document.getElementById(id);
            if (!el) return;
            el.addEventListener('change', refreshSchemaBuilderSqlPreview);
            el.addEventListener('input', refreshSchemaBuilderSqlPreview);
        });

        const addColBtn = document.getElementById('btn-schema-add-col-row');
        if (addColBtn && colsList) {
            addColBtn.addEventListener('click', () => {
                colsList.appendChild(createSchemaColRowEl());
                const lastInp = colsList.lastElementChild && colsList.lastElementChild.querySelector('.schema-col-name-inp');
                if (lastInp) lastInp.focus();
            });
        }

        const queueBtn = document.getElementById('btn-schema-queue-custom');
        if (queueBtn) {
            queueBtn.addEventListener('click', () => {
                const op = readDraftCustomDesignerOperation();
                if (!op.tableName) {
                    setSchemaBuilderStatusHtml('error', '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Enter a valid lowercase table name (letters, numbers, underscores).');
                    return;
                }
                if (op.mode === 'add_columns' && op.columns.length === 0) {
                    setSchemaBuilderStatusHtml('error', '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Enter at least one column name before adding to the script.');
                    return;
                }
                customSchemaQueue.push(op);
                if (colsList) {
                    colsList.innerHTML = '';
                    colsList.appendChild(createSchemaColRowEl());
                }
                const newTblInp = document.getElementById('schema-new-table-name');
                if (newTblInp) newTblInp.value = '';
                renderCustomSchemaQueueUI();
                setSchemaBuilderStatusHtml('success', `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> Added <code>public.${escapeHtml(op.tableName)}</code> to the provisioning script! Click <strong>Create Tables &amp; Columns Now (1-Click)</strong> or <strong>Copy SQL &amp; Open SQL Editor</strong>.`);
            });
        }

        const scanBtn = document.getElementById('btn-scan-crm-schema');
        if (scanBtn) scanBtn.addEventListener('click', window.scanCrmDatabaseSchemaUI);

        const runBtn = document.getElementById('btn-run-crm-schema');
        if (runBtn) runBtn.addEventListener('click', window.runCrmSchemaProvisioningUI);

        const copyOpenBtn = document.getElementById('btn-copy-open-sql-editor');
        if (copyOpenBtn) copyOpenBtn.addEventListener('click', window.copyAndOpenSupabaseSqlEditorUI);

        const toggleSqlBtn = document.getElementById('btn-toggle-schema-sql');
        const sqlWrap = document.getElementById('schema-builder-sql-wrap');
        if (toggleSqlBtn && sqlWrap) {
            toggleSqlBtn.addEventListener('click', () => {
                refreshSchemaBuilderSqlPreview();
                const willOpen = sqlWrap.hidden;
                sqlWrap.hidden = !willOpen;
                toggleSqlBtn.setAttribute('aria-expanded', String(willOpen));
            });
        }

        renderSchemaHealthGrid(null);
        refreshSchemaBuilderSqlPreview();
    }

    initCrmSchemaBuilderUI();

    // --- SUPABASE DATABASE EXPORT & BACKUP SYSTEM ---
    function updateLastExportBadge(iso) {
        const badgeText = document.getElementById('supabase-last-export-text');
        const badgeEl = document.getElementById('supabase-last-export-badge');
        const stored = iso || localStorage.getItem('supabase_last_export_timestamp');
        if (stored && badgeText) {
            const d = new Date(stored);
            if (!isNaN(d.getTime())) {
                const timeStr = d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                badgeText.textContent = `Last export: ${timeStr}`;
                if (badgeEl) {
                    badgeEl.style.background = '#dcfce7';
                    badgeEl.style.color = '#15803d';
                    badgeEl.style.borderColor = '#bbf7d0';
                }
            }
        }
    }
    window.updateLastExportBadge = updateLastExportBadge;

    function updateLastRestoreBadge(iso) {
        const badgeText = document.getElementById('supabase-last-restore-text');
        const badgeEl = document.getElementById('supabase-last-restore-badge');
        const stored = iso || localStorage.getItem('supabase_last_restore_timestamp');
        if (stored && badgeText) {
            const d = new Date(stored);
            if (!isNaN(d.getTime())) {
                const timeStr = d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                badgeText.textContent = `Last restore: ${timeStr}`;
                if (badgeEl) {
                    badgeEl.style.background = '#eff6ff';
                    badgeEl.style.color = '#1d4ed8';
                    badgeEl.style.borderColor = '#bfdbfe';
                }
            }
        }
    }
    window.updateLastRestoreBadge = updateLastRestoreBadge;

    function exportLocalStorageBackup() {
        const currentUser = (typeof loggedInUser !== 'undefined' && loggedInUser) ? loggedInUser.username : (localStorage.getItem('loggedInUser') || 'Admin');
        const now = new Date();
        const pad = (n) => String(n).padStart(2, '0');
        const timestampStr = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
        
        const backupData = {
            metadata: {
                version: "2.0",
                app: "MyFactorySpace",
                system: "LocalStorage Backup Fallback",
                exported_at: now.toISOString(),
                exported_by: currentUser,
                format: "application/json"
            },
            summary: {
                properties: (safeJsonParse('industria_properties', [])).length,
                parks: Object.keys(safeJsonParse('industria_parks', {})).length,
                leads: (safeJsonParse('industria_leads', [])).length,
                owner_listings: (safeJsonParse('industria_owner_listings', [])).length,
                agents: (safeJsonParse('industria_agents', [])).length
            },
            storage: {
                properties: safeJsonParse('industria_properties', []),
                parks: safeJsonParse('industria_parks', {}),
                leads: safeJsonParse('industria_leads', []),
                owner_listings: safeJsonParse('industria_owner_listings', []),
                agents: safeJsonParse('industria_agents', []),
                settings: safeJsonParse('industria_settings', {}),
                branding: safeJsonParse('industria_branding_settings', {})
            }
        };

        const jsonString = JSON.stringify(backupData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json;charset=utf-8' });
        const downloadUrl = URL.createObjectURL(blob);
        const fileName = `myfactoryspace_local_backup_${timestampStr}.json`;

        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(downloadUrl), 1000);
    }

    window.exportSupabaseDatabase = async function() {
        const btn = document.getElementById('btn-export-supabase-db');
        const icon = document.getElementById('export-db-icon');
        const label = document.getElementById('export-db-label');
        const originalLabel = label ? label.textContent : 'Download Complete Database Backup (.json)';
        
        if (btn) btn.disabled = true;
        if (icon) icon.className = 'fa-solid fa-spinner fa-spin';
        if (label) label.textContent = 'Fetching tables from Supabase...';

        try {
            if (!window.IndustraSupabase) {
                throw new Error('Supabase client not initialized');
            }
            const client = window.IndustraSupabase.getClient();
            if (!client) throw new Error('Supabase client unavailable');

            // Fetch all tables in parallel
            const [
                propsRes,
                parksRes,
                leadsRes,
                ownersRes,
                agentsRes,
                usersRes,
                settingsRes,
                templatesRes
            ] = await Promise.all([
                client.from('properties').select('*').order('id', { ascending: true }),
                client.from('parks').select('*').order('id', { ascending: true }),
                client.from('leads').select('*').order('id', { ascending: false }),
                client.from('owner_listings').select('*').order('id', { ascending: false }),
                client.from('agents').select('*').order('id', { ascending: true }),
                client.from('app_users').select('*').order('created_at', { ascending: true }),
                client.from('site_settings').select('*'),
                client.from('automation_templates').select('*')
            ]);

            const currentUser = (typeof loggedInUser !== 'undefined' && loggedInUser) ? loggedInUser.username : (localStorage.getItem('loggedInUser') || 'Admin');
            const now = new Date();
            const pad = (n) => String(n).padStart(2, '0');
            const timestampStr = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
            const isoString = now.toISOString();

            const backupData = {
                metadata: {
                    version: "2.0",
                    app: "MyFactorySpace",
                    system: "Supabase Cloud PostgreSQL Backup",
                    project_id: (window.IndustraSupabase && typeof window.IndustraSupabase.getActiveDbUrl === 'function' ? extractSupabaseProjectRef(window.IndustraSupabase.getActiveDbUrl()) : '') || "vnsinkesbbikeqbywxfd",
                    exported_at: isoString,
                    exported_by: currentUser,
                    format: "application/json"
                },
                summary: {
                    properties: (propsRes.data || []).length,
                    parks: (parksRes.data || []).length,
                    leads: (leadsRes.data || []).length,
                    owner_listings: (ownersRes.data || []).length,
                    agents: (agentsRes.data || []).length,
                    app_users: (usersRes.data || []).length,
                    site_settings: (settingsRes.data || []).length,
                    automation_templates: (templatesRes.data || []).length
                },
                tables: {
                    properties: propsRes.data || [],
                    parks: parksRes.data || [],
                    leads: leadsRes.data || [],
                    owner_listings: ownersRes.data || [],
                    agents: agentsRes.data || [],
                    app_users: usersRes.data || [],
                    site_settings: settingsRes.data || [],
                    automation_templates: templatesRes.data || []
                }
            };

            const jsonString = JSON.stringify(backupData, null, 2);
            const blob = new Blob([jsonString], { type: 'application/json;charset=utf-8' });
            const downloadUrl = URL.createObjectURL(blob);
            const fileName = `myfactoryspace_supabase_backup_${timestampStr}.json`;

            const a = document.createElement('a');
            a.href = downloadUrl;
            a.download = fileName;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(() => URL.revokeObjectURL(downloadUrl), 1000);

            // Record last backup timestamp
            localStorage.setItem('supabase_last_export_timestamp', isoString);
            updateLastExportBadge(isoString);

            if (typeof showDensityToast === 'function') {
                showDensityToast(`Database exported! Downloaded: ${fileName}`);
            } else {
                alert(`✅ Database Export Complete!\n\nDownloaded: ${fileName}\n\nTables backed up:\n• Properties: ${backupData.summary.properties}\n• Parks: ${backupData.summary.parks}\n• Leads: ${backupData.summary.leads}\n• Owner Listings: ${backupData.summary.owner_listings}\n• Agents: ${backupData.summary.agents}\n• App Users: ${backupData.summary.app_users}\n• Settings: ${backupData.summary.site_settings}`);
            }

        } catch (err) {
            console.error('Database export error:', err);
            alert(`⚠️ Database Export Notice:\n\nCloud export error: ${err.message}\n\nDownloading LocalStorage backup instead...`);
            exportLocalStorageBackup();
        } finally {
            if (btn) btn.disabled = false;
            if (icon) icon.className = 'fa-solid fa-cloud-arrow-down';
            if (label) label.textContent = originalLabel;
        }
    };

    window.copySupabaseSummaryJson = async function() {
        try {
            const text = `MyFactorySpace Database Summary (${new Date().toLocaleString()}):\n` +
                `• Properties: ${document.getElementById('supabase-count-properties')?.textContent || 'N/A'}\n` +
                `• Parks: ${document.getElementById('supabase-count-parks')?.textContent || 'N/A'}\n` +
                `• User Accounts: ${document.getElementById('supabase-count-users')?.textContent || 'N/A'}\n` +
                `• Leads: ${document.getElementById('supabase-count-leads')?.textContent || 'N/A'}`;
            await navigator.clipboard.writeText(text);
            if (typeof showDensityToast === 'function') {
                showDensityToast('Database summary copied to clipboard!');
            } else {
                alert('Database summary copied to clipboard!');
            }
        } catch (e) {
            console.warn('Clipboard write error:', e);
        }
    };

