        setVal('setting-maintenance-title', settings.maintenanceTitle || 'Website Under Maintenance');
        setVal('setting-maintenance-message', settings.maintenanceMessage || 'We are currently performing scheduled upgrades and system maintenance to serve you better. Please check back shortly.');
        const maintShowContactEl = document.getElementById('setting-maintenance-show-contact');
        if (maintShowContactEl) {
            maintShowContactEl.checked = settings.maintenanceShowContact !== false && String(settings.maintenanceShowContact) !== 'false';
        }
