    function describeGoogleMapsErrorCode(errorCode) {
        const originPattern = ((window.location && window.location.origin) ? window.location.origin : 'https://www.myfactoryspace.com') + '/*';
        const code = String(errorCode || '').trim();
        if (code === 'RefererNotAllowedMapError') {
            return {
                title: 'HTTP Referrer Restricted (RefererNotAllowedMapError)',
                fix: `Your Google Maps API key is restricted to specific websites in Google Cloud Console, and the current URL is not on its allow-list. In <strong>Google Cloud Console &rarr; APIs &amp; Services &rarr; Credentials &rarr; Your API Key &rarr; Website restrictions</strong>, add <code>${originPattern}</code> (plus <code>https://www.myfactoryspace.com/*</code> and <code>https://myfactoryspace.com/*</code>), then click Save.`
            };
        }
        if (code === 'ApiNotActivatedMapError') {
            return {
                title: 'Maps JavaScript API Not Enabled (ApiNotActivatedMapError)',
                fix: 'Your API key exists, but the <strong>Maps JavaScript API</strong> service is not enabled on that Google Cloud project yet. In <strong>Google Cloud Console &rarr; APIs &amp; Services &rarr; Library</strong>, search for <strong>Maps JavaScript API</strong> and click <strong>Enable</strong>.'
            };
        }
        if (code === 'BillingNotEnabledMapError') {
            return {
                title: 'Billing Not Linked on Project (BillingNotEnabledMapError)',
                fix: 'Google requires an active Cloud Billing Account linked to the exact Google Cloud Project that owns this API key to unlock the 10,000 free monthly map loads. In <strong>Google Cloud Console &rarr; Billing</strong>, link your billing account to this project.'
            };
        }
        if (code === 'InvalidKeyMapError') {
            return {
                title: 'Invalid API Key (InvalidKeyMapError)',
                fix: 'Google rejected this key string as invalid. Double-check that the full <code>AIzaSy...</code> key was copied accurately from <strong>Google Cloud Console &rarr; Credentials</strong> without extra characters.'
            };
        }
        if (code === 'ExpiredKeyMapError' || code === 'OverQuotaMapError') {
            return {
                title: `Key Quota or Expiration Issue (${code})`,
                fix: 'This API key has either expired or reached its configured daily/monthly quota limit in Google Cloud Console.'
            };
        }
        return {
            title: code ? `Google Maps Authentication Rejected (${code})` : 'Google Maps Authentication / Billing / Referrer Rejected',
            fix: `Google Maps SDK triggered <code>gm_authFailure</code> and automatically fell back to free Esri maps. Please verify in <strong>Google Cloud Console</strong>: (1) <strong>Maps JavaScript API</strong> is enabled in API Library, (2) <strong>Billing</strong> is linked to this project, and (3) <strong>HTTP Referrers</strong> allow <code>${originPattern}</code>.`
        };
    }

    function renderGoogleMapsDiagnosticBox(state, detail) {
        const box = document.getElementById('setting-gmaps-diagnostic-box');
        if (!box) return;
        if (!state || state === 'empty') {
            box.style.display = 'none';
            box.innerHTML = '';
            return;
        }
        box.style.display = 'block';
        if (state === 'verifying') {
            box.style.background = '#eff6ff';
            box.style.border = '1px solid #bfdbfe';
            box.style.color = '#1e40af';
            box.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px;"></i> <strong>Verifying API Key with Google Maps servers...</strong>';
            return;
        }
        if (state === 'verified') {
            box.style.background = '#ecfdf5';
            box.style.border = '1px solid #6ee7b7';
            box.style.color = '#065f46';
            box.innerHTML = '<i class="fa-solid fa-circle-check" style="margin-right:6px;color:#059669;"></i> <strong>Google Maps Active &amp; Verified:</strong> Google authenticated your API key on this domain. All public maps and the coordinate picker are rendering genuine Google Maps (<em>Map data &copy;2026 Google</em>).';
            return;
        }
        if (state === 'auth-failed') {
            const info = describeGoogleMapsErrorCode(detail && detail.errorCode);
            box.style.background = '#fffbeb';
            box.style.border = '1px solid #fcd34d';
            box.style.color = '#92400e';
            box.innerHTML = `
                <div style="font-weight:700;margin-bottom:4px;color:#b45309;">
                    <i class="fa-solid fa-triangle-exclamation" style="margin-right:6px;"></i> Why your map is still showing Esri: ${info.title}
                </div>
                <div style="color:#78350f;">${info.fix}</div>
                <div style="margin-top:6px;font-size:0.77rem;color:#92400e;">
                    <em>While this Google Cloud issue is active, MyFactorySpace automatically displays free Esri Street &amp; Satellite maps so visitors never see broken or watermarked maps. Once fixed in Google Cloud Console, click <strong>Verify Key</strong> or <strong>Save Map Settings</strong>.</em>
                </div>
            `;
        }
    }

    let lastVerifiedGmapsKey = '';
    let gmapsVerifyInFlight = false;

    async function verifyAndRenderGoogleMapsStatus(apiKeyVal) {
        const pill = document.getElementById('setting-gmaps-status-pill');
        const cleaned = String(apiKeyVal || '').trim();
        if (!cleaned) {
            if (pill) {
                pill.textContent = 'Free Map Active';
                pill.style.background = '#ecfdf5';
                pill.style.color = '#047857';
                pill.style.borderColor = '#a7f3d0';
            }
            renderGoogleMapsDiagnosticBox('empty');
            return { valid: false, status: 'empty' };
        }

        if (!window.IndustraMap || typeof window.IndustraMap.verifyGoogleMapsApiKey !== 'function') {
            return { valid: false, status: 'unavailable' };
        }

        if (gmapsVerifyInFlight) return null;
        gmapsVerifyInFlight = true;

        if (pill) {
            pill.textContent = 'Verifying Google Key...';
            pill.style.background = '#eff6ff';
            pill.style.color = '#1d4ed8';
            pill.style.borderColor = '#93c5fd';
        }
        renderGoogleMapsDiagnosticBox('verifying');

        try {
            const res = await window.IndustraMap.verifyGoogleMapsApiKey(cleaned);
            lastVerifiedGmapsKey = cleaned;
            if (res && res.valid) {
                if (pill) {
                    pill.textContent = 'Google Maps Active (Verified)';
                    pill.style.background = '#dbeafe';
                    pill.style.color = '#1d4ed8';
                    pill.style.borderColor = '#93c5fd';
                }
                renderGoogleMapsDiagnosticBox('verified', res);
            } else {
                if (pill) {
                    pill.textContent = (res && res.errorCode) ? `Esri Fallback (${res.errorCode})` : 'Esri Fallback (Auth/Billing Check)';
                    pill.style.background = '#fef3c7';
                    pill.style.color = '#b45309';
                    pill.style.borderColor = '#fcd34d';
                }
                renderGoogleMapsDiagnosticBox('auth-failed', res);
            }
            return res;
        } finally {
            gmapsVerifyInFlight = false;
        }
    }

    function updateGoogleMapsStatusPill(apiKeyVal, opts) {
        const pill = document.getElementById('setting-gmaps-status-pill');
        if (!pill) return;
        const cleaned = String(apiKeyVal || '').trim();
        const hasKey = !!cleaned;
        if (hasKey) {
            pill.textContent = 'Google Maps Key Configured';
            pill.style.background = '#dbeafe';
            pill.style.color = '#1d4ed8';
            pill.style.borderColor = '#93c5fd';
            if (opts && opts.autoVerify && cleaned !== lastVerifiedGmapsKey) {
                verifyAndRenderGoogleMapsStatus(cleaned);
            }
        } else {
            lastVerifiedGmapsKey = '';
            pill.textContent = 'Free Map Active';
            pill.style.background = '#ecfdf5';
            pill.style.color = '#047857';
            pill.style.borderColor = '#a7f3d0';
            renderGoogleMapsDiagnosticBox('empty');
        }
    }

    window.addEventListener('mfs:gmaps-status', (ev) => {
        const d = (ev && ev.detail) || {};
        if (d.status === 'auth-failed') {
            const pill = document.getElementById('setting-gmaps-status-pill');
            if (pill) {
                pill.textContent = d.errorCode ? `Esri Fallback (${d.errorCode})` : 'Esri Fallback (Auth/Billing Check)';
                pill.style.background = '#fef3c7';
                pill.style.color = '#b45309';
                pill.style.borderColor = '#fcd34d';
            }
            renderGoogleMapsDiagnosticBox('auth-failed', d);
        }
    });

