    const mapsSettingsForm = document.getElementById('settings-maps-form');
    if (mapsSettingsForm) {
        mapsSettingsForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const keyVal = gmapsKeyInput ? gmapsKeyInput.value.trim() : '';
            settings.googleMapsApiKey = keyVal;
            localStorage.setItem('industria_settings', JSON.stringify(settings));
            updateGoogleMapsStatusPill(keyVal);
            if (window.IndustraMap && typeof window.IndustraMap.setGoogleMapsApiKey === 'function') {
                window.IndustraMap.setGoogleMapsApiKey(keyVal, { forceRetry: true });
            }
            window.dispatchEvent(new Event('storage'));
            await saveGeneralSettingsToSupabase();
            if (typeof window.logDashboardActivity === 'function') {
                window.logDashboardActivity({
                    category: 'Settings',
                    action: 'Update',
                    target: 'Interactive Map Settings',
                    details: keyVal ? 'Configured Google Maps API Key' : 'Cleared Google Maps API Key (Free Map Active)'
                });
            }
            if (!keyVal) {
                alert('Map settings saved! Free keyless Esri Street & Satellite maps are active.');
                return;
            }
            const verifyRes = await verifyAndRenderGoogleMapsStatus(keyVal);
            if (verifyRes && verifyRes.valid) {
                alert('Google Maps API Key saved & verified! All public maps are now displaying genuine Google Maps ("Map data ©2026 Google").');
            } else {
                const errInfo = describeGoogleMapsErrorCode(verifyRes && verifyRes.errorCode);
                alert(`Google Maps API Key saved, but Google rejected the key right now (${errInfo.title}).\n\nPublic maps are safely staying on free Esri maps until this is enabled in Google Cloud Console. See the yellow diagnostic box under the API key field for the exact fix.`);
            }
        });
    }

    // --- TIME ZONE & REGIONAL MANAGEMENT FORM HANDLERS ---
